#define WIFI_INFO(...) syslog(LOG_INFO, WIFI_LOG_TAG ": " __VA_ARGS__)

/* esp_hosted SDIO protocol constants (from esp_hosted spec) */

#define ESP_HOSTED_CHANNEL_CTRL   0
#define ESP_HOSTED_CHANNEL_DATA   1
#define ESP_HOSTED_HEADER_LEN     8

