 * Private Types
 ****************************************************************************/

/* Per-packet header for esp_hosted SDIO protocol */

struct esp_hosted_header_s
{
  uint8_t  channel;    /* 0=control, 1=data */
  uint8_t  reserved;
  uint16_t len;        /* payload length */
  uint16_t offset;     /* offset to payload */
  uint16_t checksum;   /* header checksum */
};

/* Driver private data */

struct esp_wifi_dev_s
{
  struct net_driver_s  netdev;       /* NuttX network device */
  struct work_s        pollwork;     /* Deferred poll work */
  struct sdio_dev_s   *sdio;        /* SDIO device handle */
  bool                 ifup;        /* Interface is up */
  bool                 connected;   /* WiFi connected */
  uint8_t              mac[6];      /* MAC address */
};

