329	static int esp_hosted_pb_put_varint(FAR uint8_t *buf, size_t buflen,
330	                                    uint64_t value)
331	{
332	  size_t offset = 0;
333	
334	  do
335	    {
336	      uint8_t byte;
337	
338	      if (offset >= buflen)
339	        {
340	          return -ENOSPC;
341	        }
342	
343	      byte = value & 0x7f;
344	      value >>= 7;
345	
346	      if (value != 0)
347	        {
348	          byte |= 0x80;
349	        }
350	
351	      buf[offset++] = byte;
352	    }
353	  while (value != 0);
354	
355	  return offset;
356	}
