397	static int esp_hosted_pb_append_bytes_field(FAR uint8_t *buf, size_t buflen,
398	                                            FAR size_t *offset,
399	                                            uint32_t field,
400	                                            FAR const uint8_t *value,
401	                                            size_t value_len)
402	{
403	  int ret;
404	
405	  ret = esp_hosted_pb_append_key(buf, buflen, offset, field,
406	                                 ESP_HOSTED_PB_WIRE_LENGTH);
407	  if (ret < 0)
408	    {
409	      return ret;
410	    }
411	
412	  ret = esp_hosted_pb_append_varint(buf, buflen, offset, value_len);
413	  if (ret < 0)
414	    {
415	      return ret;
416	    }
417	
418	  if (value_len > buflen - *offset)
419	    {
420	      return -ENOSPC;
421	    }
422	
423	  if (value_len > 0)
424	    {
425	      memcpy(buf + *offset, value, value_len);
426	      *offset += value_len;
427	    }
428	
429	  return OK;
430	}
