432	static int esp_hosted_pb_get_varint(FAR const uint8_t *buf, size_t len,
433	                                    FAR size_t *offset,
434	                                    FAR uint64_t *value)
435	{
436	  uint64_t result = 0;
437	  unsigned int shift = 0;
438	
439	  while (*offset < len && shift < 64)
440	    {
441	      uint8_t byte = buf[(*offset)++];
442	
443	      result |= ((uint64_t)(byte & 0x7f)) << shift;
444	      if ((byte & 0x80) == 0)
445	        {
446	          *value = result;
447	          return OK;
448	        }
449	
450	      shift += 7;
451	    }
452	
453	  return -EINVAL;
454	}
455	
456	static int esp_hosted_pb_skip_field(FAR const uint8_t *buf, size_t len,
457	                                    FAR size_t *offset, uint8_t wire_type)
458	{
459	  uint64_t value;
460	  int ret;
461	
462	  switch (wire_type)
463	    {
464	      case ESP_HOSTED_PB_WIRE_VARINT:
465	        return esp_hosted_pb_get_varint(buf, len, offset, &value);
466	
467	      case ESP_HOSTED_PB_WIRE_64BIT:
468	        if (len - *offset < 8)
469	          {
470	            return -EINVAL;
471	          }
472	
473	        *offset += 8;
474	        return OK;
475	
476	      case ESP_HOSTED_PB_WIRE_LENGTH:
477	        ret = esp_hosted_pb_get_varint(buf, len, offset, &value);
478	        if (ret < 0 || value > len - *offset)
479	          {
480	            return -EINVAL;
481	          }
482	
483	        *offset += value;
484	        return OK;
485	
486	      case ESP_HOSTED_PB_WIRE_32BIT:
487	        if (len - *offset < 4)
488	          {
489	            return -EINVAL;
490	          }
491	
492	        *offset += 4;
493	        return OK;
494	
495	      default:
496	        return -EINVAL;
497	    }
498	}
