536	static int esp_hosted_pserial_wrap(FAR struct esp_hosted_driver_s *priv,
537	                                   FAR const char *epname,
538	                                   FAR const uint8_t *payload,
539	                                   size_t payload_len,
540	                                   FAR uint8_t *out,
541	                                   size_t out_size,
542	                                   FAR size_t *out_len)
543	{
544	  size_t ep_len;
545	  size_t total_len;
546	  size_t offset = 0;
547	
548	  ep_len = strlen(epname);
549	  if (ep_len == 0 || ep_len > UINT16_MAX ||
550	      ep_len > ESP_HOSTED_PSER_TLV_MAX_EP || payload_len > UINT16_MAX)
551	    {
552	      priv->stats.rpc_tlv_error_count++;
553	      return -EINVAL;
554	    }
555	
556	  total_len = 1 + ESP_HOSTED_PSER_TLV_LEN_SIZE + ep_len +
557	              1 + ESP_HOSTED_PSER_TLV_LEN_SIZE + payload_len;
558	  if (total_len > out_size)
559	    {
560	      priv->stats.rpc_tlv_error_count++;
561	      return -ENOSPC;
562	    }
563	
564	  out[offset++] = ESP_HOSTED_PSER_TLV_TYPE_EPNAME;
565	  esp_hosted_put_le16(&out[offset], ep_len);
566	  offset += ESP_HOSTED_PSER_TLV_LEN_SIZE;
567	  memcpy(&out[offset], epname, ep_len);
568	  offset += ep_len;
569	
570	  out[offset++] = ESP_HOSTED_PSER_TLV_TYPE_DATA;
571	  esp_hosted_put_le16(&out[offset], payload_len);
572	  offset += ESP_HOSTED_PSER_TLV_LEN_SIZE;
573	  memcpy(&out[offset], payload, payload_len);
574	  offset += payload_len;
575	
576	  *out_len = offset;
577	  priv->stats.rpc_tlv_tx_count++;
578	  return OK;
579	}
