581	static int esp_hosted_pserial_unwrap(FAR struct esp_hosted_driver_s *priv,
582	                                     FAR const uint8_t *payload,
583	                                     size_t payload_len,
584	                                     FAR const uint8_t **rpc_payload,
585	                                     FAR size_t *rpc_len)
586	{
587	  FAR const uint8_t *data = NULL;
588	  char epname[ESP_HOSTED_PSER_TLV_MAX_EP + 1];
589	  size_t data_len = 0;
590	  size_t offset = 0;
591	  bool have_epname = false;
592	  bool have_data = false;
593	
594	  memset(epname, 0, sizeof(epname));
595	
596	  while (offset < payload_len)
597	    {
598	      uint8_t type;
599	      uint16_t len;
600	
601	      if (payload_len - offset < 1 + ESP_HOSTED_PSER_TLV_LEN_SIZE)
602	        {
603	          priv->stats.rpc_tlv_error_count++;
604	          return -EINVAL;
605	        }
606	
607	      type = payload[offset++];
608	      len = esp_hosted_get_le16(&payload[offset]);
609	      offset += ESP_HOSTED_PSER_TLV_LEN_SIZE;
610	
611	      if (len > payload_len - offset)
612	        {
613	          priv->stats.rpc_tlv_error_count++;
614	          return -EINVAL;
615	        }
616	
617	      switch (type)
618	        {
619	          case ESP_HOSTED_PSER_TLV_TYPE_EPNAME:
620	            if (len == 0 || len > ESP_HOSTED_PSER_TLV_MAX_EP)
621	              {
622	                priv->stats.rpc_tlv_error_count++;
623	                return -EINVAL;
624	              }
625	
626	            memcpy(epname, &payload[offset], len);
627	            epname[len] = '\0';
628	            have_epname = true;
629	            break;
630	
631	          case ESP_HOSTED_PSER_TLV_TYPE_DATA:
632	            data = &payload[offset];
633	            data_len = len;
634	            have_data = true;
635	            break;
636	
637	          default:
638	            priv->stats.rpc_tlv_error_count++;
639	            return -EINVAL;
640	        }
641	
642	      offset += len;
643	    }
644	
645	  if (!have_epname || !have_data || data_len == 0 ||
646	      (strcmp(epname, ESP_HOSTED_RPC_EP_NAME_RSP) != 0 &&
647	       strcmp(epname, ESP_HOSTED_RPC_EP_NAME_EVT) != 0))
648	    {
649	      priv->stats.rpc_tlv_error_count++;
650	      nwarn("ESP-Hosted invalid pserial TLV: ep=%s have_data=%d len=%zu\n",
651	            have_epname ? epname : "<none>", have_data, data_len);
652	      return -EINVAL;
653	    }
654	
655	  *rpc_payload = data;
656	  *rpc_len = data_len;
657	  priv->stats.rpc_tlv_rx_count++;
658	  return OK;
659	}
