1034	static int esp_hosted_queue_sta_frame(FAR struct esp_hosted_driver_s *priv,
1035	                                      FAR const uint8_t *payload,
1036	                                      uint16_t len)
1037	{
1038	  FAR netpkt_t *pkt;
1039	  irqstate_t flags;
1040	  int ret;
1041	
1042	  if (!priv->wlan_registered)
1043	    {
1044	      priv->stats.netdev_rx_dropped_count++;
1045	      return OK;
1046	    }
1047	
1048	  if (len >= ETH_HDRLEN &&
1049	      memcmp(((FAR const struct eth_hdr_s *)payload)->src, priv->mac,
1050	             ESP_HOSTED_MAC_SIZE) == 0)
1051	    {
1052	      priv->stats.netdev_rx_echo_dropped_count++;
1053	      return OK;
1054	    }
1055	
1056	  pkt = netpkt_alloc(&priv->lower, NETPKT_RX);
1057	  if (pkt == NULL)
1058	    {
1059	      priv->stats.netdev_rx_dropped_count++;
1060	      return -ENOMEM;
1061	    }
1062	
1063	  ret = netpkt_copyin(&priv->lower, pkt, payload, len, 0);
1064	  if (ret < 0)
1065	    {
1066	      priv->stats.netdev_rx_dropped_count++;
1067	      netpkt_free(&priv->lower, pkt, NETPKT_RX);
1068	      return ret;
1069	    }
1070	
1071	  flags = spin_lock_irqsave(&priv->rx_lock);
1072	  ret = netpkt_tryadd_queue(pkt, &priv->rx_queue);
1073	  if (ret >= 0)
1074	    {
1075	      priv->stats.current_rx_queue_depth++;
1076	      if (priv->stats.current_rx_queue_depth >
1077	          priv->stats.rx_queue_max_depth)
1078	        {
1079	          priv->stats.rx_queue_max_depth =
1080	            priv->stats.current_rx_queue_depth;
1081	        }
1082	    }
1083	
1084	  spin_unlock_irqrestore(&priv->rx_lock, flags);
1085	  if (ret < 0)
1086	    {
1087	      priv->stats.netdev_rx_dropped_count++;
1088	      netpkt_free(&priv->lower, pkt, NETPKT_RX);
1089	      return ret;
1090	    }
1091	
1092	  priv->stats.netdev_rx_count++;
1093	  priv->stats.last_rx_ticks = clock_systime_ticks();
1094	  netdev_lower_rxready(&priv->lower);
1095	  return OK;
1096	}
1097	#endif
