1099	static int esp_hosted_parse_rpc_message(FAR const uint8_t *payload,
1100	                                        uint16_t len,
1101	                                        FAR struct esp_hosted_rpc_message_s
1102	                                        *msg)
1103	{
1104	  size_t offset = 0;
1105	  int ret;
1106	
1107	  memset(msg, 0, sizeof(*msg));
1108	
1109	  while (offset < len)
1110	    {
1111	      uint64_t key;
1112	      uint32_t field;
1113	      uint8_t wire_type;
1114	
1115	      ret = esp_hosted_pb_get_varint(payload, len, &offset, &key);
1116	      if (ret < 0 || key == 0)
1117	        {
1118	          return -EINVAL;
1119	        }
1120	
1121	      field = key >> 3;
1122	      wire_type = key & 0x07;
1123	
1124	      switch (field)
1125	        {
1126	          case ESP_HOSTED_RPC_FIELD_MSG_TYPE:
1127	          case ESP_HOSTED_RPC_FIELD_MSG_ID:
1128	          case ESP_HOSTED_RPC_FIELD_UID:
1129	            {
1130	              uint64_t value;
1131	
1132	              if (wire_type != ESP_HOSTED_PB_WIRE_VARINT)
1133	                {
1134	                  return -EINVAL;
1135	                }
1136	
1137	              ret = esp_hosted_pb_get_varint(payload, len, &offset, &value);
1138	              if (ret < 0)
1139	                {
1140	                  return ret;
1141	                }
1142	
1143	              if (field == ESP_HOSTED_RPC_FIELD_MSG_TYPE)
1144	                {
1145	                  msg->msg_type = value;
1146	                }
1147	              else if (field == ESP_HOSTED_RPC_FIELD_MSG_ID)
1148	                {
1149	                  msg->msg_id = value;
1150	                }
1151	              else
1152	                {
1153	                  msg->uid = value;
1154	                }
1155	            }
1156	            break;
1157	
1158	          default:
1159	            if (wire_type == ESP_HOSTED_PB_WIRE_LENGTH && field >= 256)
1160	              {
1161	                uint64_t value_len;
1162	
1163	                ret = esp_hosted_pb_get_varint(payload, len, &offset,
1164	                                               &value_len);
1165	                if (ret < 0 || value_len > len - offset)
1166	                  {
1167	                    return -EINVAL;
1168	                  }
1169	
1170	                msg->payload_field = field;
1171	                msg->payload = payload + offset;
1172	                msg->payload_len = value_len;
1173	                offset += value_len;
1174	            }
1175	            else
1176	              {
1177	                ret = esp_hosted_pb_skip_field(payload, len, &offset,
1178	                                               wire_type);
1179	                if (ret < 0)
1180	                  {
1181	                    return ret;
1182	                  }
1183	              }
1184	            break;
1185	        }
1186	    }
1187	
1188	  return OK;
1189	}
