1193	                                         size_t len)
1194	{
1195	  size_t offset = 0;
1196	  int32_t resp = 0;
1197	  bool have_mac = false;
1198	  uint8_t mac[ESP_HOSTED_MAC_SIZE];
1199	  int ret;
1200	
1201	  memset(mac, 0, sizeof(mac));
1202	
1203	  while (offset < len)
1204	    {
1205	      uint64_t key;
1206	      uint32_t field;
1207	      uint8_t wire_type;
1208	
1209	      ret = esp_hosted_pb_get_varint(payload, len, &offset, &key);
1210	      if (ret < 0 || key == 0)
1211	        {
1212	          return -EINVAL;
1213	        }
1214	
1215	      field = key >> 3;
1216	      wire_type = key & 0x07;
1217	
1218	      switch (field)
1219	        {
1220	          case 1:
1221	            {
1222	              uint64_t value_len;
1223	
1224	              if (wire_type != ESP_HOSTED_PB_WIRE_LENGTH)
1225	                {
1226	                  return -EINVAL;
1227	                }
1228	
1229	              ret = esp_hosted_pb_get_varint(payload, len, &offset,
