1232	                  value_len < ESP_HOSTED_MAC_SIZE)
1233	                {
1234	                  return -EINVAL;
1235	                }
1236	
1237	              memcpy(mac, payload + offset, ESP_HOSTED_MAC_SIZE);
1238	              offset += value_len;
1239	              have_mac = true;
1240	            }
1241	            break;
1242	
1243	          case 2:
1244	            {
1245	              uint64_t value;
1246	
1247	              if (wire_type != ESP_HOSTED_PB_WIRE_VARINT)
1248	                {
1249	                  return -EINVAL;
1250	                }
1251	
1252	              ret = esp_hosted_pb_get_varint(payload, len, &offset, &value);
1253	              if (ret < 0)
1254	                {
1255	                  return ret;
1256	                }
1257	
1258	              resp = esp_hosted_pb_int32(value);
1259	            }
1260	            break;
1261	
1262	          default:
1263	            ret = esp_hosted_pb_skip_field(payload, len, &offset, wire_type);
