1265	              {
1266	                return ret;
1267	              }
1268	            break;
1269	        }
1270	    }
1271	
1272	  if (!have_mac)
1273	    {
1274	      if (resp != 0)
1275	        {
1276	          nwarn("ESP-Hosted MAC response failed: resp=%" PRId32 "\n", resp);
1277	#ifdef CONFIG_ESP_HOSTED_WLAN
1278	          priv->mac_probe_sent = false;
1279	#endif
1280	          return -EIO;
1281	        }
1282	
1283	      return -EINVAL;
1284	    }
1285	
1286	  if (resp != 0)
1287	    {
1288	      nwarn("ESP-Hosted MAC response failed: resp=%" PRId32 "\n", resp);
1289	#ifdef CONFIG_ESP_HOSTED_WLAN
1290	      priv->mac_probe_sent = false;
1291	#endif
1292	      return -EIO;
1293	    }
1294	
1295	  memcpy(priv->mac, mac, sizeof(priv->mac));
1296	  priv->have_mac = true;
1297	  priv->stats.rpc_mac_count++;
1298	
1299	  ninfo("ESP-Hosted STA MAC: %02x:%02x:%02x:%02x:%02x:%02x resp=%" PRId32
1300	        "\n",
1301	        mac[0], mac[1], mac[2], mac[3], mac[4], mac[5], resp);
1302	
1303	#ifdef CONFIG_ESP_HOSTED_WLAN
1304	  priv->mac_probe_sent = true;
1305	  esp_hosted_try_register_wlan(priv);
1306	#endif
1307	
1308	  return OK;
1309	}
