1372	                {
1373	                  version.build = esp_hosted_pb_int32(value);
1374	                }
1375	            }
1376	            break;
1377	
1378	          case 2:
1379	          case 3:
1380	          case 4:
1381	          case 8:
1382	            {
1383	              uint64_t value;
1384	
1385	              if (wire_type != ESP_HOSTED_PB_WIRE_VARINT)
