1392	                {
1393	                  return ret;
1394	                }
1395	
1396	              if (field == 2)
1397	                {
1398	                  version.major = value;
1399	                }
1400	              else if (field == 3)
1401	                {
1402	                  version.minor = value;
1403	                }
1404	              else if (field == 4)
1405	                {
1406	                  version.patch = value;
1407	                }
1408	              else
1409	                {
