1411	                }
1412	            }
1413	            break;
1414	
1415	          case 9:
1416	            {
1417	              uint64_t value_len;
1418	              size_t copy_len;
1419	
1420	              if (wire_type != ESP_HOSTED_PB_WIRE_LENGTH)
1421	                {
1422	                  return -EINVAL;
1423	                }
1424	
1425	              ret = esp_hosted_pb_get_varint(payload, len, &offset,
