1442	                }
1443	
1444	              offset += value_len;
1445	            }
1446	            break;
1447	
1448	          default:
1449	            ret = esp_hosted_pb_skip_field(payload, len, &offset, wire_type);
1450	            if (ret < 0)
1451	              {
1452	                return ret;
1453	              }
1454	            break;
1455	        }
1456	    }
1457	
1458	  priv->fwversion = version;
1459	  priv->have_fwversion = true;
1460	  priv->stats.rpc_fwversion_count++;
1461	
1462	  ninfo("ESP-Hosted firmware: %" PRIu32 ".%" PRIu32 ".%" PRIu32
