1464	        version.major, version.minor, version.patch, version.idf_target,
1465	        version.chip_id, version.resp);
1466	
1467	#ifdef CONFIG_ESP_HOSTED_WLAN
1468	  if (!priv->wlan_control_started)
1469	    {
1470	      priv->wlan_control_start_pending = true;
1471	    }
1472	
1473	  esp_hosted_try_register_wlan(priv);
1474	#endif
1475	
1476	  return OK;
1477	}
