1718	      uint32_t field;
1719	      uint8_t wire_type;
1720	
1721	      ret = esp_hosted_pb_get_varint(payload, len, &offset, &key);
1722	      if (ret < 0 || key == 0)
1723	        {
1724	          return -EINVAL;
1725	        }
1726	
1727	      field = key >> 3;
1728	      wire_type = key & 0x07;
1729	
1730	      switch (field)
1731	        {
1732	          case 1:
1733	            if (wire_type != ESP_HOSTED_PB_WIRE_LENGTH)
1734	              {
1735	                return -EINVAL;
1736	              }
1737	
1738	            ret = esp_hosted_pb_get_bytes(payload, len, &offset,
1739	                                          &value_ptr, &value_len);
1740	            if (ret < 0 || value_len < ESP_HOSTED_MAC_SIZE)
1741	              {
1742	                return -EINVAL;
1743	              }
1744	
1745	            memcpy(record->bssid, value_ptr, ESP_HOSTED_MAC_SIZE);
1746	            have_bssid = true;
1747	            break;
1748	
1749	          case 2:
1750	            if (wire_type != ESP_HOSTED_PB_WIRE_LENGTH)
1751	              {
1752	                return -EINVAL;
1753	              }
1754	
1755	            ret = esp_hosted_pb_get_bytes(payload, len, &offset,
1756	                                          &value_ptr, &value_len);
1757	            if (ret < 0)
1758	              {
1759	                return ret;
1760	              }
1761	
1762	            copy_len = value_len;
1763	            if (copy_len > 0 && value_ptr[copy_len - 1] == '\0')
1764	              {
1765	                copy_len--;
1766	              }
1767	
1768	            if (copy_len > IW_ESSID_MAX_SIZE)
1769	              {
1770	                copy_len = IW_ESSID_MAX_SIZE;
1771	              }
1772	
1773	            if (copy_len > 0)
1774	              {
1775	                memcpy(record->ssid, value_ptr, copy_len);
1776	              }
1777	
1778	            record->ssid[copy_len] = '\0';
1779	            record->ssid_len = copy_len;
1780	            break;
1781	
1782	          case 3:
1783	          case 5:
1784	          case 6:
1785	            if (wire_type != ESP_HOSTED_PB_WIRE_VARINT)
1786	              {
1787	                return -EINVAL;
1788	              }
1789	
1790	            ret = esp_hosted_pb_get_varint(payload, len, &offset, &value);
1791	            if (ret < 0)
1792	              {
1793	                return ret;
1794	              }
1795	
1796	            if (field == 3)
1797	              {
1798	                record->channel = value > UINT8_MAX ? UINT8_MAX : value;
1799	              }
1800	            else if (field == 5)
1801	              {
1802	                record->rssi = esp_hosted_pb_int32(value);
1803	              }
1804	            else
1805	              {
1806	                record->authmode = esp_hosted_pb_int32(value);
1807	              }
1808	            break;
1809	
1810	          default:
1811	            ret = esp_hosted_pb_skip_field(payload, len, &offset, wire_type);
1812	            if (ret < 0)
1813	              {
1814	                return ret;
1815	              }
1816	            break;
1817	        }
1818	    }
1819	
1820	  return have_bssid ? OK : -EINVAL;
1821	}
