1823	static int esp_hosted_parse_scan_records_response(
1824	  FAR struct esp_hosted_driver_s *priv, FAR const uint8_t *payload,
1825	  size_t len)
1826	{
1827	  struct esp_hosted_scan_record_s records[ESP_HOSTED_SCAN_MAX_APS];
1828	  size_t offset = 0;
1829	  int32_t resp = 0;
1830	  uint32_t number = 0;
1831	  uint16_t count = 0;
1832	  int ret;
1833	
1834	  memset(records, 0, sizeof(records));
1835	
1836	  while (offset < len)
1837	    {
1838	      FAR const uint8_t *value_ptr;
1839	      uint64_t key;
1840	      uint64_t value;
1841	      size_t value_len;
1842	      uint32_t field;
1843	      uint8_t wire_type;
1844	
1845	      ret = esp_hosted_pb_get_varint(payload, len, &offset, &key);
1846	      if (ret < 0 || key == 0)
1847	        {
1848	          return -EINVAL;
1849	        }
1850	
1851	      field = key >> 3;
1852	      wire_type = key & 0x07;
1853	
1854	      switch (field)
1855	        {
1856	          case 1:
1857	          case 2:
1858	            if (wire_type != ESP_HOSTED_PB_WIRE_VARINT)
1859	              {
1860	                return -EINVAL;
1861	              }
1862	
1863	            ret = esp_hosted_pb_get_varint(payload, len, &offset, &value);
1864	            if (ret < 0)
1865	              {
1866	                return ret;
1867	              }
1868	
1869	            if (field == 1)
1870	              {
1871	                resp = esp_hosted_pb_int32(value);
1872	              }
1873	            else
1874	              {
1875	                number = value;
1876	              }
1877	            break;
1878	
1879	          case 3:
1880	            if (wire_type != ESP_HOSTED_PB_WIRE_LENGTH)
1881	              {
1882	                return -EINVAL;
1883	              }
1884	
1885	            ret = esp_hosted_pb_get_bytes(payload, len, &offset,
1886	                                          &value_ptr, &value_len);
1887	            if (ret < 0)
1888	              {
1889	                return ret;
1890	              }
1891	
1892	            if (count < ESP_HOSTED_SCAN_MAX_APS)
1893	              {
1894	                ret = esp_hosted_parse_ap_record(&records[count],
1895	                                                 value_ptr, value_len);
1896	                if (ret < 0)
1897	                  {
1898	                    return ret;
1899	                  }
1900	
1901	                count++;
1902	              }
1903	            break;
1904	
1905	          default:
1906	            ret = esp_hosted_pb_skip_field(payload, len, &offset, wire_type);
1907	            if (ret < 0)
1908	              {
1909	                return ret;
1910	              }
1911	            break;
1912	        }
1913	    }
1914	
1915	  if (resp != 0)
1916	    {
1917	      priv->stats.wlan_scan_get_records_error_count++;
1918	      nwarn("ESP-Hosted scan records failed: resp=%" PRId32 "\n", resp);
1919	      return -EIO;
1920	    }
1921	
1922	  memcpy(priv->scan_records, records, sizeof(records));
1923	  priv->scan_result_count = count;
1924	  priv->scan_ap_available = number > ESP_HOSTED_SCAN_MAX_APS ?
1925	                            ESP_HOSTED_SCAN_MAX_APS : number;
1926	  priv->scan_records_valid = true;
1927	  priv->scan_done = true;
1928	  priv->scan_in_progress = false;
1929	  priv->stats.wlan_scan_get_records_count++;
1930	  priv->stats.wlan_scan_result_count += count;
1931	
1932	  ninfo("ESP-Hosted scan records: reported=%" PRIu32 " cached=%u\n",
1933	        number, count);
1934	  return OK;
1935	}
