1990	static int esp_hosted_parse_control_frame(FAR struct esp_hosted_driver_s *priv,
1991	                                          FAR const uint8_t *payload,
1992	                                          uint16_t len)
1993	{
1994	  FAR const uint8_t *rpc_payload;
1995	  size_t rpc_len;
1996	  struct esp_hosted_rpc_message_s msg;
1997	  int ret;
1998	
1999	  ret = esp_hosted_pserial_unwrap(priv, payload, len, &rpc_payload,
2000	                                  &rpc_len);
2001	  if (ret < 0)
2002	    {
2003	      priv->stats.rpc_malformed_count++;
2004	      return ret;
2005	    }
2006	
2007	  ret = esp_hosted_parse_rpc_message(rpc_payload, rpc_len, &msg);
2008	  if (ret < 0)
2009	    {
2010	      priv->stats.rpc_malformed_count++;
2011	      return ret;
2012	    }
2013	
2014	  priv->stats.rpc_last_uid = msg.uid;
2015	
2016	  if (msg.msg_type == ESP_HOSTED_RPC_TYPE_RESP)
2017	    {
2018	      priv->stats.rpc_response_count++;
2019	      priv->stats.rpc_last_response_id = msg.msg_id;
2020	
2021	      if (msg.payload_field != msg.msg_id)
2022	        {
2023	          priv->stats.rpc_malformed_count++;
