2025	                " payload=%" PRIu32 "\n",
2026	                msg.msg_id, msg.payload_field);
2027	          return -EINVAL;
2028	        }
2029	
2030	      switch (msg.msg_id)
2031	        {
2032	          int32_t resp;
2033	
2034	          case ESP_HOSTED_RPC_RESP_GET_MAC_ADDRESS:
2035	            return esp_hosted_parse_mac_response(priv, msg.payload,
