2038	          case ESP_HOSTED_RPC_RESP_GET_COPROCESSOR_FWVERSION:
2039	            return esp_hosted_parse_fwversion_response(priv, msg.payload,
2040	                                                       msg.payload_len);
2041	
2042	          case ESP_HOSTED_RPC_RESP_SET_MODE:
2043	          case ESP_HOSTED_RPC_RESP_WIFI_INIT:
2044	          case ESP_HOSTED_RPC_RESP_WIFI_START:
2045	          case ESP_HOSTED_RPC_RESP_WIFI_CONNECT:
2046	          case ESP_HOSTED_RPC_RESP_WIFI_DISCONNECT:
2047	          case ESP_HOSTED_RPC_RESP_WIFI_SET_CONFIG:
2048	          case ESP_HOSTED_RPC_RESP_WIFI_SCAN_START:
2049	          case ESP_HOSTED_RPC_RESP_WIFI_SCAN_GET_AP_NUM:
2050	            ret = esp_hosted_parse_response_status(msg.payload,
2051	                                                   msg.payload_len, &resp);
2052	            if (ret < 0)
2053	              {
2054	                return ret;
2055	              }
2056	
2057	            if (resp != 0)
2058	              {
2059	                priv->stats.rpc_malformed_count++;
2060	                nwarn("ESP-Hosted RPC response failed: id=%" PRIu32
2061	                      " resp=%" PRId32 "\n",
2062	                      msg.msg_id, resp);
2063	                return -EIO;
2064	              }
2065	
2066	            ninfo("ESP-Hosted RPC response OK: id=%" PRIu32
2067	                  " uid=%" PRIu32 "\n",
2068	                  msg.msg_id, msg.uid);
2069	            return OK;
2070	
2071	          case ESP_HOSTED_RPC_RESP_WIFI_SCAN_GET_AP_RECORDS:
2072	#ifdef CONFIG_ESP_HOSTED_WLAN
2073	            return esp_hosted_parse_scan_records_response(priv, msg.payload,
2074	                                                          msg.payload_len);
2075	#else
2076	            return OK;
2077	#endif
2078	
2079	          default:
2080	            ninfo("ESP-Hosted RPC response: id=%" PRIu32 " uid=%" PRIu32
2081	                  " len=%zu\n",
2082	                  msg.msg_id, msg.uid, msg.payload_len);
2083	            return OK;
2084	        }
2085	    }
2086	  else if (msg.msg_type == ESP_HOSTED_RPC_TYPE_EVENT)
2087	    {
2088	      priv->stats.rpc_event_count++;
2089	
2090	      switch (msg.msg_id)
2091	        {
2092	#ifdef CONFIG_ESP_HOSTED_WLAN
2093	          case ESP_HOSTED_RPC_EVENT_STA_SCAN_DONE:
2094	            return esp_hosted_parse_sta_scan_done_event(priv, msg.payload,
2095	                                                        msg.payload_len);
2096	
2097	          case ESP_HOSTED_RPC_EVENT_STA_CONNECTED:
2098	            return esp_hosted_parse_sta_connected_event(priv, msg.payload,
2099	                                                        msg.payload_len);
2100	
2101	          case ESP_HOSTED_RPC_EVENT_STA_DISCONNECTED:
2102	            return esp_hosted_parse_sta_disconnected_event(priv, msg.payload,
2103	                                                           msg.payload_len);
2104	#endif
2105	
2106	          default:
2107	            ninfo("ESP-Hosted RPC event: id=%" PRIu32 " uid=%" PRIu32
2108	                  " len=%zu\n",
2109	                  msg.msg_id, msg.uid, msg.payload_len);
2110	            return OK;
2111	        }
2112	    }
2113	
2114	  priv->stats.rpc_malformed_count++;
2115	  nwarn("ESP-Hosted unexpected RPC message: type=%" PRIu32 " id=%" PRIu32
2116	        " uid=%" PRIu32 "\n",
2117	        msg.msg_type, msg.msg_id, msg.uid);
2118	
2119	  return -EINVAL;
2120	}
