2354	                                     FAR uint8_t *frame)
2355	{
2356	  FAR struct esp_hosted_payload_header_s *header;
2357	  FAR uint8_t *payload;
2358	  enum esp_hosted_if_type_e if_type;
2359	  uint16_t len;
2360	  uint16_t offset;
2361	  uint16_t checksum;
2362	  uint16_t expected;
2363	  int ret = OK;
2364	
2365	  header = (FAR struct esp_hosted_payload_header_s *)frame;
2366	  if_type = ESP_HOSTED_HDR_IF_TYPE(header);
2367	  len = le16toh(header->len);
2368	  offset = le16toh(header->offset);
2369	
2370	  if (len == 0)
2371	    {
2372	      priv->stats.rx_dummy_count++;
2373	      return OK;
2374	    }
2375	
2376	  if (len > ESP_HOSTED_MAX_PAYLOAD || offset != ESP_HOSTED_HEADER_LEN ||
2377	      offset + len > ESP_HOSTED_SPI_MAX_FRAME)
2378	    {
2379	      priv->stats.malformed_frame_count++;
2380	      nwarn("ESP-Hosted malformed frame: if=%u len=%u offset=%u\n",
2381	            if_type, len, offset);
2382	      return -EINVAL;
2383	    }
2384	
2385	  checksum = le16toh(header->checksum);
2386	  expected = esp_hosted_frame_checksum(frame, offset + len);
2387	  if (checksum != expected)
2388	    {
2389	      priv->stats.checksum_error_count++;
2390	      nwarn("ESP-Hosted checksum mismatch: rx=%04x expected=%04x\n",
2391	            checksum, expected);
2392	      return -EIO;
2393	    }
2394	
2395	  priv->stats.rx_frame_count++;
2396	  priv->stats.last_rx_ticks = clock_systime_ticks();
2397	  payload = frame + offset;
2398	
2399	  switch (if_type)
2400	    {
2401	      case ESP_HOSTED_STA_IF:
2402	        priv->stats.rx_sta_count++;
2403	#ifdef CONFIG_ESP_HOSTED_WLAN
2404	        ret = esp_hosted_queue_sta_frame(priv, payload, len);
2405	#endif
2406	        break;
2407	
2408	      case ESP_HOSTED_AP_IF:
2409	        priv->stats.rx_ap_count++;
2410	        break;
2411	
2412	      case ESP_HOSTED_SERIAL_IF:
2413	        priv->stats.rx_control_count++;
2414	        ret = esp_hosted_parse_control_frame(priv, payload, len);
2415	        if (ret < 0)
2416	          {
2417	            priv->stats.malformed_frame_count++;
2418	          }
2419	        break;
2420	
2421	      case ESP_HOSTED_PRIV_IF:
2422	        ret = esp_hosted_parse_priv_frame(priv, payload, len);
2423	        if (ret < 0)
2424	          {
2425	            priv->stats.malformed_frame_count++;
2426	          }
2427	        break;
2428	
2429	      default:
2430	        priv->stats.rx_unknown_count++;
2431	        nwarn("ESP-Hosted unsupported frame: if=%u len=%u\n", if_type, len);
2432	        break;
2433	    }
2434	
2435	  return ret;
2436	}
