2461	static int esp_hosted_schedule_rx_work_delay(
2462	  FAR struct esp_hosted_driver_s *priv, clock_t delay, bool idle)
2463	{
2464	  int ret;
2465	
2466	  if (delay > 0)
2467	    {
2468	      if (!work_available(&priv->poll_work))
2469	        {
2470	          priv->stats.rx_poll_busy_count++;
2471	          return -EBUSY;
2472	        }
2473	
2474	      ret = work_queue(ESP_HOSTED_WORK_QUEUE, &priv->poll_work,
2475	                       esp_hosted_rx_poll_work, priv, delay);
2476	      if (ret >= 0)
2477	        {
2478	          if (idle)
2479	            {
2480	              priv->stats.rx_idle_poll_count++;
2481	            }
2482	          else
2483	            {
2484	              priv->stats.rx_poll_count++;
2485	            }
2486	        }
2487	
2488	      return ret;
2489	    }
2490	
2491	  if (!work_available(&priv->rx_work))
2492	    {
2493	      priv->stats.rx_work_busy_count++;
2494	    }
2495	
2496	  ret = work_queue(ESP_HOSTED_WORK_QUEUE, &priv->rx_work,
2497	                   esp_hosted_rx_work, priv, 0);
2498	  if (ret >= 0)
2499	    {
2500	      priv->stats.rx_work_count++;
2501	    }
2502	
2503	  return ret;
2504	}
