2512	static void esp_hosted_arm_rx_poll(FAR struct esp_hosted_driver_s *priv,
2513	                                   uint8_t budget)
2514	{
2515	  if (budget > priv->rx_poll_budget)
2516	    {
2517	      priv->rx_poll_budget = budget;
2518	    }
2519	}
