2521	
2522	static void esp_hosted_schedule_rx_poll(FAR struct esp_hosted_driver_s *priv)
2523	{
2524	#ifdef CONFIG_ESP_HOSTED_WLAN
2525	  if (priv->wlan_registered && priv->ifup && priv->carrier_on)
2526	    {
2527	      bool burst = priv->rx_poll_budget > 0;
2528	      int ret;
2529	
2530	      if (burst)
2531	        {
2532	          priv->rx_force_poll = true;
2533	          if (!work_available(&priv->poll_work))
2534	            {
2535	              (void)work_cancel(ESP_HOSTED_WORK_QUEUE, &priv->poll_work);
2536	            }
2537	        }
2538	
2539	      /* Burst polls follow TX, IRQ, or link-up activity and need a short,
2540	       * sustained polling window.  esp_hosted_schedule_rx_work_delay() skips
2541	       * retiming an already queued delayed poll, so repeated TX packets cannot
2542	       * keep pushing the receive worker into the future.
2543	       */
2544	
2545	      ret = esp_hosted_schedule_rx_work_delay(priv,
2546	        MSEC2TICK(burst ? ESP_HOSTED_RX_POLL_DELAY_MS :
2547	                          ESP_HOSTED_RX_IDLE_POLL_DELAY_MS),
2548	        !burst);
2549	      if (ret >= 0 && burst)
2550	        {
2551	          priv->rx_poll_budget--;
2552	        }
2553	      else if (ret < 0 && burst)
2554	        {
2555	          esp_hosted_schedule_rx_work(priv);
2556	        }
2557	    }
2558	#endif
2559	}
