2611	static int esp_hosted_spi_exchange_frame(FAR struct esp_hosted_driver_s *priv,
2612	                                         FAR const void *txbuf,
2613	                                         FAR void *rxbuf)
2614	{
2615	  FAR struct spi_dev_s *spi = priv->config.spi;
2616	  int ret;
2617	
2618	  ret = esp_hosted_wait_handshake(priv);
2619	  if (ret < 0)
2620	    {
2621	      return ret;
2622	    }
2623	
2624	  ret = SPI_LOCK(spi, true);
2625	  if (ret < 0)
2626	    {
2627	      return ret;
2628	    }
2629	
2630	  esp_hosted_spi_configure(priv);
2631	
2632	  SPI_SELECT(spi, priv->config.spi_devid, true);
2633	  SPI_EXCHANGE(spi, txbuf, rxbuf, ESP_HOSTED_SPI_MAX_FRAME);
2634	  SPI_SELECT(spi, priv->config.spi_devid, false);
2635	
2636	  SPI_LOCK(spi, false);
2637	
2638	  priv->stats.spi_transaction_count++;
2639	  return OK;
2640	}
