2679	static int esp_hosted_wlan_transmit(FAR struct netdev_lowerhalf_s *dev,
2680	                                    FAR netpkt_t *pkt)
2681	{
2682	  FAR struct esp_hosted_driver_s *priv =
2683	    (FAR struct esp_hosted_driver_s *)dev;
2684	  unsigned int len;
2685	  int parse_ret = OK;
2686	  int ret;
2687	
2688	  len = netpkt_getdatalen(dev, pkt);
2689	  priv->stats.netdev_tx_last_len = len;
2690	  priv->stats.netdev_tx_last_ret = OK;
2691	  priv->stats.netdev_tx_last_parse_ret = OK;
2692	
2693	  if (!priv->ifup)
2694	    {
2695	      priv->stats.netdev_tx_error_count++;
2696	      priv->stats.netdev_tx_last_ret = -ENETDOWN;
2697	      return -ENETDOWN;
2698	    }
2699	
2700	  if (!priv->carrier_on)
2701	    {
2702	      priv->stats.netdev_tx_error_count++;
2703	      priv->stats.netdev_tx_carrier_off_count++;
2704	      priv->stats.netdev_tx_last_ret = -ENETDOWN;
2705	      netdev_lower_carrier_off(&priv->lower);
2706	      return -ENETDOWN;
2707	    }
2708	
2709	  if (len > ESP_HOSTED_MAX_PAYLOAD)
2710	    {
2711	      priv->stats.netdev_tx_error_count++;
2712	      priv->stats.netdev_tx_oversize_count++;
2713	      priv->stats.netdev_tx_last_ret = -EMSGSIZE;
2714	      return -EMSGSIZE;
2715	    }
2716	
2717	  ret = nxmutex_lock(&priv->lock);
2718	  if (ret < 0)
2719	    {
2720	      priv->stats.netdev_tx_error_count++;
2721	      priv->stats.netdev_tx_last_ret = ret;
2722	      return ret;
2723	    }
2724	
2725	  ret = netpkt_copyout(dev, priv->netdev_tx_payload, pkt, len, 0);
2726	  if (ret < 0)
2727	    {
2728	      nxmutex_unlock(&priv->lock);
2729	      priv->stats.netdev_tx_error_count++;
2730	      priv->stats.netdev_tx_copy_error_count++;
2731	      priv->stats.netdev_tx_last_ret = ret;
2732	      return ret;
2733	    }
2734	
2735	  esp_hosted_build_header(priv, priv->tx_frame, ESP_HOSTED_STA_IF, 0, 0,
2736	                          priv->netdev_tx_payload, len);
2737	  memset(priv->rx_frame, 0, sizeof(priv->rx_frame));
2738	
2739	  ret = esp_hosted_spi_exchange_frame(priv, priv->tx_frame, priv->rx_frame);
2740	  if (ret >= 0)
2741	    {
2742	      parse_ret = esp_hosted_parse_rx_frame(priv, priv->rx_frame);
2743	      priv->stats.netdev_tx_last_parse_ret = parse_ret;
2744	      if (parse_ret < 0)
2745	        {
2746	          priv->stats.netdev_tx_parse_error_count++;
2747	          nwarn("ESP-Hosted STA TX side RX parse failed: %d\n", parse_ret);
2748	        }
2749	    }
2750	  else
2751	    {
2752	      priv->stats.netdev_tx_last_ret = ret;
2753	    }
2754	
2755	  nxmutex_unlock(&priv->lock);
2756	
2757	  if (ret < 0)
2758	    {
2759	      priv->stats.netdev_tx_error_count++;
2760	      priv->stats.netdev_tx_spi_error_count++;
2761	      return ret;
2762	    }
2763	
2764	  priv->stats.netdev_tx_count++;
2765	  priv->stats.netdev_tx_last_ret = OK;
2766	  netpkt_free(dev, pkt, NETPKT_TX);
2767	  netdev_lower_txdone(dev);
2768	  esp_hosted_arm_rx_poll(priv, ESP_HOSTED_RX_POLL_TX_BUDGET);
2769	  esp_hosted_schedule_rx_poll(priv);
2770	  return OK;
2771	}
