3038	static size_t esp_hosted_wlan_scan_result_len(
3039	  FAR const struct esp_hosted_driver_s *priv)
3040	{
3041	  size_t len = 0;
3042	  uint16_t i;
3043	
3044	  for (i = 0; i < priv->scan_result_count; i++)
3045	    {
3046	      len += IW_EV_LEN(ap_addr) + IW_EV_LEN(qual) +
3047	             IW_EV_LEN(freq) + IW_EV_LEN(data) + IW_EV_LEN(essid) +
3048	             ((priv->scan_records[i].ssid_len + 3) & ~3);
3049	    }
3050	
3051	  return len;
3052	}
3053	
3054	static int esp_hosted_wlan_format_scan_results(
3055	  FAR struct esp_hosted_driver_s *priv, FAR struct iwreq *iwr)
3056	{
3057	  FAR struct esp_hosted_scan_record_s *record;
3058	  FAR struct iw_event *iwe;
3059	  FAR char *pointer;
3060	  size_t need_len;
3061	  uint16_t i;
3062	
3063	  if (iwr == NULL)
3064	    {
3065	      return -EINVAL;
3066	    }
3067	
3068	  if (priv->scan_result_count == 0)
3069	    {
3070	      iwr->u.data.length = 0;
3071	      return OK;
3072	    }
3073	
3074	  need_len = esp_hosted_wlan_scan_result_len(priv);
3075	  if (iwr->u.data.pointer == NULL || iwr->u.data.length < need_len)
3076	    {
3077	      iwr->u.data.length = need_len;
3078	      return -E2BIG;
3079	    }
3080	
3081	  pointer = iwr->u.data.pointer;
3082	
3083	  for (i = 0; i < priv->scan_result_count; i++)
3084	    {
3085	      record = &priv->scan_records[i];
3086	
3087	      iwe = (FAR struct iw_event *)pointer;
3088	      iwe->cmd = SIOCGIWAP;
3089	      iwe->u.ap_addr.sa_family = ARPHRD_ETHER;
3090	      memcpy(iwe->u.ap_addr.sa_data, record->bssid, ESP_HOSTED_MAC_SIZE);
3091	      iwe->len = IW_EV_LEN(ap_addr);
3092	      pointer += iwe->len;
3093	
3094	      iwe = (FAR struct iw_event *)pointer;
3095	      iwe->cmd = SIOCGIWESSID;
3096	      iwe->u.essid.flags = 0;
3097	      iwe->u.essid.length = record->ssid_len;
3098	      iwe->u.essid.pointer = (FAR void *)sizeof(iwe->u.essid);
3099	      memcpy(&iwe->u.essid + 1, record->ssid, iwe->u.essid.length);
3100	      iwe->len = IW_EV_LEN(essid) + ((iwe->u.essid.length + 3) & ~3);
3101	      pointer += iwe->len;
3102	
3103	      iwe = (FAR struct iw_event *)pointer;
3104	      iwe->cmd = IWEVQUAL;
3105	      iwe->u.qual.qual = 0;
3106	      iwe->u.qual.level = record->rssi;
3107	      iwe->u.qual.noise = 0;
3108	      iwe->u.qual.updated = IW_QUAL_DBM | IW_QUAL_ALL_UPDATED;
3109	      iwe->len = IW_EV_LEN(qual);
3110	      pointer += iwe->len;
3111	
3112	      iwe = (FAR struct iw_event *)pointer;
3113	      iwe->cmd = SIOCGIWFREQ;
3114	      iwe->u.freq.e = 0;
3115	      iwe->u.freq.m = record->channel;
3116	      iwe->len = IW_EV_LEN(freq);
3117	      pointer += iwe->len;
3118	
3119	      iwe = (FAR struct iw_event *)pointer;
3120	      iwe->cmd = SIOCGIWENCODE;
3121	      iwe->u.data.flags = record->authmode == ESP_HOSTED_WIFI_AUTH_OPEN ?
3122	                          IW_ENCODE_DISABLED :
3123	                          IW_ENCODE_ENABLED | IW_ENCODE_NOKEY;
3124	      iwe->u.data.length = 0;
3125	      iwe->u.data.pointer = NULL;
3126	      iwe->len = IW_EV_LEN(data);
3127	      pointer += iwe->len;
3128	    }
3129	
3130	  iwr->u.data.length = pointer - (FAR char *)iwr->u.data.pointer;
3131	  return OK;
3132	}
