3134	static int esp_hosted_wlan_scan(FAR struct netdev_lowerhalf_s *dev,
3135	                                FAR struct iwreq *iwr, bool set)
3136	{
3137	  FAR struct esp_hosted_driver_s *priv =
3138	    (FAR struct esp_hosted_driver_s *)dev;
3139	  int ret;
3140	
3141	  if (!set)
3142	    {
3143	      if (iwr == NULL)
3144	        {
3145	          return -EINVAL;
3146	        }
3147	
3148	      if (priv->scan_in_progress || !priv->scan_done)
3149	        {
3150	          return -EAGAIN;
3151	        }
3152	
3153	      if (priv->scan_status != 0)
3154	        {
3155	          iwr->u.data.length = 0;
3156	          return -EIO;
3157	        }
3158	
3159	      if (!priv->scan_records_valid)
3160	        {
3161	          if (priv->scan_ap_available == 0)
3162	            {
3163	              priv->scan_records_valid = true;
3164	              priv->scan_result_count = 0;
3165	            }
3166	          else
3167	            {
3168	              priv->scan_request_count = priv->scan_ap_available;
3169	              ret = esp_hosted_send_rpc_request(priv,
3170	                ESP_HOSTED_RPC_WIFI_SCAN_GET_AP_RECORDS);
3171	              if (ret < 0)
3172	                {
3173	                  return ret;
3174	                }
3175	
3176	              if (!priv->scan_records_valid)
3177	                {
3178	                  return -EAGAIN;
3179	                }
3180	            }
3181	        }
3182	
3183	      return esp_hosted_wlan_format_scan_results(priv, iwr);
3184	    }
3185	
3186	  ret = esp_hosted_run_wlan_control_start(priv);
3187	  if (ret < 0)
3188	    {
3189	      return ret;
3190	    }
3191	
3192	  priv->scan_in_progress = true;
3193	  priv->scan_done = false;
3194	  priv->scan_records_valid = false;
3195	  priv->scan_status = 0;
3196	  priv->scan_ap_available = 0;
3197	  priv->scan_result_count = 0;
3198	  priv->scan_request_count = 0;
3199	  memset(priv->scan_records, 0, sizeof(priv->scan_records));
3200	
3201	  ret = esp_hosted_send_rpc_request(priv, ESP_HOSTED_RPC_WIFI_SCAN_START);
3202	  if (ret < 0)
3203	    {
3204	      priv->scan_in_progress = false;
3205	      return ret;
3206	    }
3207	
3208	  priv->stats.wlan_scan_start_count++;
3209	  return OK;
3210	}
