261	static int esp_hosted_sdio_set_blocksize(FAR struct sdio_dev_s *dev,
262	                                          uint8_t function, uint16_t blocksize)
263	{
264	  int ret;
265	  ret = esp32p4_sdmmc_io_rw_direct(dev, true, 0, 0x10 + (function * 2),
266	                                    blocksize & 0xFF, NULL);
267	  if (ret != OK) return ret;
268	  ret = esp32p4_sdmmc_io_rw_direct(dev, true, 0, 0x11 + (function * 2),
269	                                    (blocksize >> 8) & 0xFF, NULL);
270	  return ret;
271	}
