273	/* Protobuf 辅助函数 */
274	static int esp_hosted_pb_put_varint(FAR uint8_t *buf, size_t buflen,
275	                                     uint64_t value)
276	{
277	  size_t offset = 0;
278	  do
279	    {
280	      uint8_t byte;
281	      if (offset >= buflen)
282	        {
283	          return -ENOSPC;
284	        }
285	      byte = value & 0x7f;
286	      value >>= 7;
287	      if (value != 0)
288	        {
289	          byte |= 0x80;
290	        }
291	      buf[offset++] = byte;
292	    }
293	  while (value != 0);
294	  return offset;
295	}
296	
297	static int esp_hosted_pb_append_varint(FAR uint8_t *buf, size_t buflen,
298	                                        FAR size_t *offset, uint64_t value)
299	{
300	  int ret = esp_hosted_pb_put_varint(buf + *offset, buflen - *offset, value);
301	  if (ret < 0)
302	    {
303	      return ret;
304	    }
305	  *offset += ret;
306	  return OK;
307	}
308	
309	static int esp_hosted_pb_append_key(FAR uint8_t *buf, size_t buflen,
310	                                     FAR size_t *offset, uint32_t field,
311	                                     uint8_t wire_type)
312	{
313	  return esp_hosted_pb_append_varint(buf, buflen, offset,
314	                                      ((uint64_t)field << 3) | wire_type);
315	}
316	
317	static int esp_hosted_pb_append_varint_field(FAR uint8_t *buf, size_t buflen,
318	                                              FAR size_t *offset,
319	                                              uint32_t field, uint64_t value)
320	{
321	  int ret = esp_hosted_pb_append_key(buf, buflen, offset, field,
322	                                      ESP_HOSTED_PB_WIRE_VARINT);
323	  if (ret < 0)
324	    {
325	      return ret;
326	    }
327	  return esp_hosted_pb_append_varint(buf, buflen, offset, value);
328	}
329	
330	static int esp_hosted_pb_append_bytes_field(FAR uint8_t *buf, size_t buflen,
331	                                             FAR size_t *offset,
332	                                             uint32_t field,
333	                                             FAR const uint8_t *value,
334	                                             size_t value_len)
335	{
336	  int ret = esp_hosted_pb_append_key(buf, buflen, offset, field,
337	                                      ESP_HOSTED_PB_WIRE_LENGTH);
338	  if (ret < 0)
339	    {
340	      return ret;
341	    }
342	  ret = esp_hosted_pb_append_varint(buf, buflen, offset, value_len);
343	  if (ret < 0)
344	    {
345	      return ret;
346	    }
347	  if (value_len > buflen - *offset)
348	    {
349	      return -ENOSPC;
350	    }
351	  if (value_len > 0)
352	    {
353	      memcpy(buf + *offset, value, value_len);
354	      *offset += value_len;
355	    }
356	  return OK;
357	}
358	
359	static int esp_hosted_pb_get_varint(FAR const uint8_t *buf, size_t len,
360	                                     FAR size_t *offset, FAR uint64_t *value)
361	{
362	  uint64_t result = 0;
363	  unsigned int shift = 0;
364	  while (*offset < len && shift < 64)
365	    {
366	      uint8_t byte = buf[(*offset)++];
367	      result |= ((uint64_t)(byte & 0x7f)) << shift;
368	      if ((byte & 0x80) == 0)
369	        {
370	          *value = result;
371	          return OK;
372	        }
373	      shift += 7;
374	    }
375	  return -EINVAL;
376	}
377	
378	static int esp_hosted_pb_skip_field(FAR const uint8_t *buf, size_t len,
379	                                     FAR size_t *offset, uint8_t wire_type)
380	{
381	  uint64_t value;
382	  int ret;
383	  switch (wire_type)
384	    {
385	      case ESP_HOSTED_PB_WIRE_VARINT:
386	        return esp_hosted_pb_get_varint(buf, len, offset, &value);
387	      case ESP_HOSTED_PB_WIRE_LENGTH:
388	        ret = esp_hosted_pb_get_varint(buf, len, offset, &value);
389	        if (ret < 0 || value > len - *offset)
390	          {
391	            return -EINVAL;
392	          }
393	        *offset += value;
394	        return OK;
395	      default:
396	        return -EINVAL;
397	    }
398	}
399	
400	static int esp_hosted_pb_get_bytes(FAR const uint8_t *buf, size_t len,
401	                                    FAR size_t *offset,
402	                                    FAR const uint8_t **value,
403	                                    FAR size_t *value_len)
404	{
405	  uint64_t field_len;
406	  int ret = esp_hosted_pb_get_varint(buf, len, offset, &field_len);
407	  if (ret < 0 || field_len > len - *offset)
408	    {
409	      return -EINVAL;
410	    }
411	  *value = buf + *offset;
412	  *value_len = field_len;
413	  *offset += field_len;
414	  return OK;
415	}
