422	static void esp_hosted_put_le16(FAR uint8_t *buf, uint16_t value)
423	{
424	  buf[0] = value & 0xff;
425	  buf[1] = value >> 8;
426	}
427	
428	static uint16_t esp_hosted_get_le16(FAR const uint8_t *buf)
429	{
430	  return (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
431	}
432	
433	static uint16_t esp_hosted_checksum(FAR const uint8_t *buf, uint16_t len)
434	{
435	  uint16_t checksum = 0;
436	  for (uint16_t i = 0; i < len; i++)
437	    {
438	      checksum += buf[i];
439	    }
440	  return checksum;
441	}
442	
443	static uint16_t esp_hosted_frame_checksum(FAR uint8_t *buf, uint16_t len)
444	{
445	  FAR struct esp_hosted_payload_header_s *header =
446	    (FAR struct esp_hosted_payload_header_s *)buf;
447	  uint16_t saved = header->checksum;
448	  header->checksum = 0;
449	  uint16_t checksum = esp_hosted_checksum(buf, len);
450	  header->checksum = saved;
451	  return checksum;
452	}
