454	/* pserial 包装 */
455	static int esp_hosted_pserial_wrap(FAR struct esp_hosted_driver_s *priv,
456	                                    FAR const char *epname,
457	                                    FAR const uint8_t *payload,
458	                                    size_t payload_len,
459	                                    FAR uint8_t *out, size_t out_size,
460	                                    FAR size_t *out_len)
461	{
462	  size_t ep_len = strlen(epname);
463	  size_t total_len = 1 + ESP_HOSTED_PSER_TLV_LEN_SIZE + ep_len +
464	                     1 + ESP_HOSTED_PSER_TLV_LEN_SIZE + payload_len;
465	  size_t offset = 0;
466	
467	  if (ep_len == 0 || ep_len > UINT16_MAX ||
468	      ep_len > ESP_HOSTED_PSER_TLV_MAX_EP || payload_len > UINT16_MAX)
469	    {
470	      priv->stats.rpc_tlv_error_count++;
471	      return -EINVAL;
472	    }
473	  if (total_len > out_size)
474	    {
475	      priv->stats.rpc_tlv_error_count++;
476	      return -ENOSPC;
477	    }
478	
479	  out[offset++] = ESP_HOSTED_PSER_TLV_TYPE_EPNAME;
480	  esp_hosted_put_le16(&out[offset], ep_len);
481	  offset += ESP_HOSTED_PSER_TLV_LEN_SIZE;
482	  memcpy(&out[offset], epname, ep_len);
483	  offset += ep_len;
484	  out[offset++] = ESP_HOSTED_PSER_TLV_TYPE_DATA;
485	  esp_hosted_put_le16(&out[offset], payload_len);
486	  offset += ESP_HOSTED_PSER_TLV_LEN_SIZE;
487	  memcpy(&out[offset], payload, payload_len);
488	  offset += payload_len;
489	  *out_len = offset;
490	  priv->stats.rpc_tlv_tx_count++;
491	  return OK;
492	}
493	
494	static int esp_hosted_pserial_unwrap(FAR struct esp_hosted_driver_s *priv,
495	                                      FAR const uint8_t *payload,
496	                                      size_t payload_len,
497	                                      FAR const uint8_t **rpc_payload,
498	                                      FAR size_t *rpc_len)
499	{
500	  FAR const uint8_t *data = NULL;
501	  char epname[ESP_HOSTED_PSER_TLV_MAX_EP + 1];
502	  size_t data_len = 0;
503	  size_t offset = 0;
504	  bool have_epname = false;
505	  bool have_data = false;
506	
507	  memset(epname, 0, sizeof(epname));
508	
509	  while (offset < payload_len)
510	    {
511	      uint8_t type;
512	      uint16_t len;
513	      if (payload_len - offset < 1 + ESP_HOSTED_PSER_TLV_LEN_SIZE)
514	        {
515	          priv->stats.rpc_tlv_error_count++;
516	          return -EINVAL;
517	        }
518	      type = payload[offset++];
519	      len = esp_hosted_get_le16(&payload[offset]);
520	      offset += ESP_HOSTED_PSER_TLV_LEN_SIZE;
521	      if (len > payload_len - offset)
522	        {
523	          priv->stats.rpc_tlv_error_count++;
524	          return -EINVAL;
525	        }
526	      switch (type)
527	        {
528	          case ESP_HOSTED_PSER_TLV_TYPE_EPNAME:
529	            if (len == 0 || len > ESP_HOSTED_PSER_TLV_MAX_EP)
530	              {
531	                priv->stats.rpc_tlv_error_count++;
532	                return -EINVAL;
533	              }
534	            memcpy(epname, &payload[offset], len);
535	            epname[len] = '\0';
536	            have_epname = true;
537	            break;
538	          case ESP_HOSTED_PSER_TLV_TYPE_DATA:
539	            data = &payload[offset];
540	            data_len = len;
541	            have_data = true;
542	            break;
543	          default:
544	            priv->stats.rpc_tlv_error_count++;
545	            return -EINVAL;
546	        }
547	      offset += len;
548	    }
549	
550	  if (!have_epname || !have_data || data_len == 0 ||
551	      (strcmp(epname, ESP_HOSTED_RPC_EP_NAME_RSP) != 0 &&
552	       strcmp(epname, ESP_HOSTED_RPC_EP_NAME_EVT) != 0))
553	    {
554	      priv->stats.rpc_tlv_error_count++;
555	      return -EINVAL;
556	    }
557	
558	  *rpc_payload = data;
559	  *rpc_len = data_len;
560	  priv->stats.rpc_tlv_rx_count++;
561	  return OK;
562	}
