693	  size_t threshold_len = 0;
694	  size_t offset = 0;
695	  int ret;
696	
697	  if (!priv->have_ssid || priv->ssid_len == 0)
698	    {
699	      return -ENOTCONN;
700	    }
701	
702	  ret = esp_hosted_pb_append_bytes_field(sta_payload, sizeof(sta_payload),
703	                                          &sta_len, 1,
704	                                          (FAR const uint8_t *)priv->ssid,
705	                                          priv->ssid_len);
706	  if (ret < 0) return ret;
707	
708	  if (priv->passphrase_len > 0)
709	    {
710	      ret = esp_hosted_pb_append_bytes_field(sta_payload,
711	                                              sizeof(sta_payload), &sta_len,
712	                                              2,
713	                                              (FAR const uint8_t *)
714	                                              priv->passphrase,
715	                                              priv->passphrase_len);
716	      if (ret < 0) return ret;
717	    }
718	
719	  ret = esp_hosted_pb_append_varint_field(sta_payload, sizeof(sta_payload),
720	                                           &sta_len, 13, 3);
721	  if (ret < 0) return ret;
722	
723	  ret = esp_hosted_pb_append_varint_field(threshold_payload,
724	                                           sizeof(threshold_payload),
725	                                           &threshold_len, 2,
726	                                           esp_hosted_wlan_authmode(priv));
727	  if (ret < 0) return ret;
728	
729	  ret = esp_hosted_pb_append_bytes_field(sta_payload, sizeof(sta_payload),
730	                                          &sta_len, 9, threshold_payload,
731	                                          threshold_len);
732	  if (ret < 0) return ret;
733	
734	  ret = esp_hosted_pb_append_bytes_field(config_payload,
735	                                          sizeof(config_payload),
736	                                          &config_len, 2,
737	                                          sta_payload, sta_len);
738	  if (ret < 0) return ret;
739	
740	  ret = esp_hosted_pb_append_varint_field(payload, payload_size, &offset, 1,
741	                                           ESP_HOSTED_WIFI_IF_STA);
742	  if (ret < 0) return ret;
743	
744	  ret = esp_hosted_pb_append_bytes_field(payload, payload_size, &offset, 2,
745	                                          config_payload, config_len);
746	  if (ret < 0) return ret;
747	
748	  *payload_len = offset;
749	  return OK;
750	}
