779	/* SDIO 交换帧：先尝试读取 RX，然后写入 TX */
780	static int esp_hosted_sdio_exchange_frame(FAR struct esp_hosted_driver_s *priv,
781	                                           FAR const uint8_t *txbuf,
782	                                           FAR uint8_t *rxbuf)
783	{
784	  FAR struct sdio_dev_s *sdio = priv->config.sdio_dev;
785	  int ret;
786	  bool rx_avail = false;
787	  uint32_t rx_len = 0;
788	
789	  /* 检查是否有 RX 数据（通过轮询或中断状态） */
790	  rx_avail = esp_hosted_sdio_rx_available(priv);
791	
792	  if (rx_avail)
793	    {
794	      /* 读取长度 */
795	      uint8_t len_bytes[4];
796	      for (int i = 0; i < 4; i++)
797	        {
798	          ret = esp_hosted_sdio_read_reg(priv, 0x0010 + i, &len_bytes[i]);
799	          if (ret != OK)
800	            {
801	              return ret;
802	            }
803	        }
804	      rx_len = (len_bytes[3] << 24) | (len_bytes[2] << 16) |
805	               (len_bytes[1] << 8) | len_bytes[0];
806	      rx_len &= 0xFFF;
807	
808	      if (rx_len > 0 && rx_len <= ESP_HOSTED_SDIO_MAX_FRAME)
809	        {
810	          ret = SDIO_IO_RW_EXTENDED(sdio, false, ESP_HOSTED_SDIO_FUNCTION,
811	                                    0, true, rxbuf, rx_len);
812	          if (ret != OK)
813	            {
814	              return ret;
815	            }
816	        }
817	      else
818	        {
819	          memset(rxbuf, 0, ESP_HOSTED_SDIO_MAX_FRAME);
820	        }
821	    }
822	  else
823	    {
824	      memset(rxbuf, 0, ESP_HOSTED_SDIO_MAX_FRAME);
825	    }
826	
827	  /* 发送 TX 帧 */
828	  if (txbuf != NULL)
829	    {
830	      uint16_t tx_len = ESP_HOSTED_SDIO_MAX_FRAME;
831	      struct esp_hosted_payload_header_s *hdr =
832	        (struct esp_hosted_payload_header_s *)txbuf;
833	      if (hdr->len > 0)
834	        {
835	          tx_len = ESP_HOSTED_HEADER_LEN + le16toh(hdr->len);
836	          if (tx_len < ESP_HOSTED_SDIO_MAX_FRAME)
837	            {
838	              tx_len = ESP_HOSTED_SDIO_MAX_FRAME;
839	            }
840	        }
841	
842	      ret = SDIO_IO_RW_EXTENDED(sdio, true, ESP_HOSTED_SDIO_FUNCTION,
843	                                0, true, (FAR uint8_t *)txbuf, tx_len);
844	      if (ret != OK)
845	        {
846	          return ret;
847	        }
848	    }
849	
850	  return OK;
851	}
