891	/* 解析 RPC 消息 */
892	static int esp_hosted_parse_rpc_message(FAR const uint8_t *payload,
893	                                         uint16_t len,
894	                                         FAR struct esp_hosted_rpc_message_s
895	                                         *msg)
896	{
897	  size_t offset = 0;
898	  int ret;
899	
900	  memset(msg, 0, sizeof(*msg));
901	
902	  while (offset < len)
903	    {
904	      uint64_t key;
905	      uint32_t field;
906	      uint8_t wire_type;
907	
908	      ret = esp_hosted_pb_get_varint(payload, len, &offset, &key);
909	      if (ret < 0 || key == 0)
910	        {
911	          return -EINVAL;
912	        }
913	
914	      field = key >> 3;
915	      wire_type = key & 0x07;
916	
917	      switch (field)
918	        {
919	          case ESP_HOSTED_RPC_FIELD_MSG_TYPE:
920	          case ESP_HOSTED_RPC_FIELD_MSG_ID:
921	          case ESP_HOSTED_RPC_FIELD_UID:
922	            {
923	              uint64_t value;
924	              if (wire_type != ESP_HOSTED_PB_WIRE_VARINT)
925	                {
926	                  return -EINVAL;
927	                }
928	              ret = esp_hosted_pb_get_varint(payload, len, &offset, &value);
929	              if (ret < 0)
930	                {
931	                  return ret;
932	                }
933	              if (field == ESP_HOSTED_RPC_FIELD_MSG_TYPE)
934	                {
935	                  msg->msg_type = value;
936	                }
937	              else if (field == ESP_HOSTED_RPC_FIELD_MSG_ID)
938	                {
939	                  msg->msg_id = value;
940	                }
941	              else
942	                {
943	                  msg->uid = value;
944	                }
945	            }
946	            break;
947	
948	          default:
949	            if (wire_type == ESP_HOSTED_PB_WIRE_LENGTH && field >= 256)
950	              {
951	                uint64_t value_len;
952	                ret = esp_hosted_pb_get_varint(payload, len, &offset,
953	                                                &value_len);
954	                if (ret < 0 || value_len > len - offset)
955	                  {
956	                    return -EINVAL;
957	                  }
958	                msg->payload_field = field;
959	                msg->payload = payload + offset;
960	                msg->payload_len = value_len;
961	                offset += value_len;
962	              }
963	            else
964	              {
965	                ret = esp_hosted_pb_skip_field(payload, len, &offset,
966	                                                wire_type);
967	                if (ret < 0)
968	                  {
969	                    return ret;
970	                  }
971	              }
972	            break;
973	        }
974	    }
975	
976	  return OK;
977	}
