979	/* 解析 MAC 响应 */
980	static int esp_hosted_parse_mac_response(FAR struct esp_hosted_driver_s *priv,
981	                                          FAR const uint8_t *payload,
982	                                          size_t len)
983	{
984	  size_t offset = 0;
985	  bool have_mac = false;
986	  uint8_t mac[ESP_HOSTED_MAC_SIZE];
987	  int ret;
988	
989	  memset(mac, 0, sizeof(mac));
990	
991	  while (offset < len)
992	    {
993	      uint64_t key;
994	      uint32_t field;
995	      uint8_t wire_type;
996	      ret = esp_hosted_pb_get_varint(payload, len, &offset, &key);
997	      if (ret < 0 || key == 0)
998	        {
999	          return -EINVAL;
1000	        }
1001	      field = key >> 3;
1002	      wire_type = key & 0x07;
1003	
1004	      switch (field)
1005	        {
1006	          case 1:
1007	            {
1008	              uint64_t value_len;
1009	              if (wire_type != ESP_HOSTED_PB_WIRE_LENGTH)
1010	                {
1011	                  return -EINVAL;
1012	                }
1013	              ret = esp_hosted_pb_get_varint(payload, len, &offset,
1014	                                              &value_len);
1015	              if (ret < 0 || value_len > len - offset ||
1016	                  value_len < ESP_HOSTED_MAC_SIZE)
1017	                {
1018	                  return -EINVAL;
1019	                }
1020	              memcpy(mac, payload + offset, ESP_HOSTED_MAC_SIZE);
1021	              offset += value_len;
1022	              have_mac = true;
1023	            }
1024	            break;
1025	
1026	          default:
1027	            ret = esp_hosted_pb_skip_field(payload, len, &offset, wire_type);
1028	            if (ret < 0)
1029	              {
1030	                return ret;
1031	              }
1032	            break;
1033	        }
1034	    }
1035	
1036	  if (!have_mac)
1037	    {
1038	      return -EINVAL;
1039	    }
1040	
1041	  memcpy(priv->mac, mac, sizeof(priv->mac));
1042	  priv->have_mac = true;
1043	  priv->stats.rpc_mac_count++;
1044	  priv->mac_probe_sent = true;
1045	
1046	  ninfo("ESP-Hosted STA MAC: %02x:%02x:%02x:%02x:%02x:%02x\n",
1047	        mac[0], mac[1], mac[2], mac[3], mac[4], mac[5]);
1048	
1049	  esp_hosted_try_register_wlan(priv);
1050	  return OK;
1051	}
