1053	/* 解析固件版本响应 */
1054	static int esp_hosted_parse_fwversion_response(
1055	  FAR struct esp_hosted_driver_s *priv, FAR const uint8_t *payload,
1056	  size_t len)
1057	{
1058	  struct esp_hosted_fwversion_s version;
1059	  size_t offset = 0;
1060	  int ret;
1061	
1062	  memset(&version, 0, sizeof(version));
1063	  version.revision = -1;
1064	  version.prerelease = -1;
1065	  version.build = -1;
1066	
1067	  while (offset < len)
1068	    {
1069	      uint64_t key;
1070	      uint32_t field;
1071	      uint8_t wire_type;
1072	      ret = esp_hosted_pb_get_varint(payload, len, &offset, &key);
1073	      if (ret < 0 || key == 0)
1074	        {
1075	          return -EINVAL;
1076	        }
1077	      field = key >> 3;
1078	      wire_type = key & 0x07;
1079	
1080	      switch (field)
1081	        {
1082	          case 1:
1083	          case 5:
1084	          case 6:
1085	          case 7:
1086	            {
1087	              uint64_t value;
1088	              if (wire_type != ESP_HOSTED_PB_WIRE_VARINT)
1089	                {
1090	                  return -EINVAL;
1091	                }
1092	              ret = esp_hosted_pb_get_varint(payload, len, &offset, &value);
1093	              if (ret < 0)
1094	                {
1095	                  return ret;
1096	                }
1097	              if (field == 1)
1098	                {
1099	                  version.resp = esp_hosted_pb_int32(value);
1100	                }
1101	              else if (field == 5 && value != 0)
1102	                {
1103	                  version.revision = esp_hosted_pb_int32(value);
1104	                }
1105	              else if (field == 6 && value != 0)
1106	                {
1107	                  version.prerelease = esp_hosted_pb_int32(value);
1108	                }
1109	              else if (field == 7 && value != 0)
1110	                {
1111	                  version.build = esp_hosted_pb_int32(value);
1112	                }
1113	            }
1114	            break;
1115	
1116	          case 2:
1117	          case 3:
1118	          case 4:
1119	          case 8:
1120	            {
1121	              uint64_t value;
1122	              if (wire_type != ESP_HOSTED_PB_WIRE_VARINT)
1123	                {
1124	                  return -EINVAL;
1125	                }
1126	              ret = esp_hosted_pb_get_varint(payload, len, &offset, &value);
1127	              if (ret < 0)
1128	                {
1129	                  return ret;
1130	                }
1131	              if (field == 2)
1132	                {
1133	                  version.major = value;
1134	                }
1135	              else if (field == 3)
1136	                {
1137	                  version.minor = value;
1138	                }
1139	              else if (field == 4)
1140	                {
1141	                  version.patch = value;
1142	                }
1143	              else
1144	                {
1145	                  version.chip_id = value;
1146	                }
1147	            }
1148	            break;
1149	
1150	          case 9:
1151	            {
1152	              uint64_t value_len;
1153	              size_t copy_len;
1154	              if (wire_type != ESP_HOSTED_PB_WIRE_LENGTH)
1155	                {
1156	                  return -EINVAL;
1157	                }
1158	              ret = esp_hosted_pb_get_varint(payload, len, &offset,
1159	                                              &value_len);
1160	              if (ret < 0 || value_len > len - offset)
1161	                {
1162	                  return -EINVAL;
1163	                }
1164	              copy_len = value_len;
1165	              if (copy_len >= sizeof(version.idf_target))
1166	                {
1167	                  copy_len = sizeof(version.idf_target) - 1;
1168	                }
1169	              if (copy_len > 0)
1170	                {
1171	                  memcpy(version.idf_target, payload + offset, copy_len);
1172	                  version.idf_target[copy_len] = '\0';
1173	                }
1174	              offset += value_len;
1175	            }
1176	            break;
1177	
1178	          default:
1179	            ret = esp_hosted_pb_skip_field(payload, len, &offset, wire_type);
1180	            if (ret < 0)
1181	              {
1182	                return ret;
1183	              }
1184	            break;
1185	        }
1186	    }
1187	
1188	  priv->fwversion = version;
1189	  priv->have_fwversion = true;
1190	  priv->stats.rpc_fwversion_count++;
1191	
1192	  ninfo("ESP-Hosted firmware: %" PRIu32 ".%" PRIu32 ".%" PRIu32
1193	        " target=%s chip=%" PRIu32 " resp=%" PRId32 "\n",
1194	        version.major, version.minor, version.patch, version.idf_target,
1195	        version.chip_id, version.resp);
1196	
1197	  if (!priv->wlan_control_started)
1198	    {
1199	      priv->wlan_control_start_pending = true;
1200	    }
1201	
1202	  esp_hosted_try_register_wlan(priv);
1203	  return OK;
1204	}
