1355	
1356	      switch (field)
1357	        {
1358	          case 1:
1359	            if (wire_type != ESP_HOSTED_PB_WIRE_VARINT)
1360	              {
1361	                return -EINVAL;
1362	              }
1363	            ret = esp_hosted_pb_get_varint(payload, len, &offset, &value);
1364	            if (ret < 0)
1365	              {
1366	                return ret;
1367	              }
1368	            resp = esp_hosted_pb_int32(value);
1369	            break;
1370	
1371	          case 2:
1372	            if (wire_type != ESP_HOSTED_PB_WIRE_LENGTH)
1373	              {
1374	                return -EINVAL;
1375	              }
1376	            ret = esp_hosted_pb_get_bytes(payload, len, &offset,
1377	                                           &scan_payload, &scan_len);
1378	            if (ret < 0)
1379	              {
1380	                return ret;
1381	              }
1382	            break;
1383	
1384	          default:
1385	            ret = esp_hosted_pb_skip_field(payload, len, &offset, wire_type);
1386	            if (ret < 0)
1387	              {
1388	                return ret;
1389	              }
1390	            break;
1391	        }
1392	    }
1393	
1394	  if (scan_payload != NULL)
1395	    {
1396	      ret = esp_hosted_parse_scan_done_payload(scan_payload, scan_len,
1397	                                                &status, &number, &scan_id);
1398	      if (ret < 0)
1399	        {
1400	          return ret;
1401	        }
1402	    }
1403	
1404	  priv->scan_in_progress = false;
1405	  priv->scan_done = true;
1406	  priv->scan_records_valid = false;
1407	  priv->scan_status = resp != 0 ? (uint32_t)resp : status;
1408	  priv->scan_ap_available = number > ESP_HOSTED_SCAN_MAX_APS ?
1409	                            ESP_HOSTED_SCAN_MAX_APS : number;
1410	  priv->scan_result_count = 0;
1411	  priv->stats.wlan_scan_done_count++;
1412	
1413	  ninfo("ESP-Hosted scan done: resp=%" PRId32 " status=%" PRIu32
1414	        " aps=%" PRIu32 " scan_id=%" PRIu32 "\n",
1415	        resp, status, number, scan_id);
1416	  return OK;
