1419	static int esp_hosted_parse_ap_record(
1420	  FAR struct esp_hosted_scan_record_s *record, FAR const uint8_t *payload,
1421	  size_t len)
1422	{
1423	  size_t offset = 0;
1424	  bool have_bssid = false;
1425	  int ret;
1426	
1427	  memset(record, 0, sizeof(*record));
1428	
1429	  while (offset < len)
1430	    {
1431	      FAR const uint8_t *value_ptr;
1432	      uint64_t key;
1433	      uint64_t value;
1434	      size_t value_len;
1435	      size_t copy_len;
1436	      uint32_t field;
1437	      uint8_t wire_type;
1438	
1439	      ret = esp_hosted_pb_get_varint(payload, len, &offset, &key);
1440	      if (ret < 0 || key == 0)
1441	        {
1442	          return -EINVAL;
1443	        }
1444	
1445	      field = key >> 3;
1446	      wire_type = key & 0x07;
1447	
1448	      switch (field)
1449	        {
1450	          case 1:
1451	            if (wire_type != ESP_HOSTED_PB_WIRE_LENGTH)
1452	              {
1453	                return -EINVAL;
1454	              }
1455	            ret = esp_hosted_pb_get_bytes(payload, len, &offset,
1456	                                           &value_ptr, &value_len);
1457	            if (ret < 0 || value_len < ESP_HOSTED_MAC_SIZE)
1458	              {
1459	                return -EINVAL;
1460	              }
1461	            memcpy(record->bssid, value_ptr, ESP_HOSTED_MAC_SIZE);
1462	            have_bssid = true;
1463	            break;
1464	
1465	          case 2:
1466	            if (wire_type != ESP_HOSTED_PB_WIRE_LENGTH)
1467	              {
1468	                return -EINVAL;
1469	              }
1470	            ret = esp_hosted_pb_get_bytes(payload, len, &offset,
1471	                                           &value_ptr, &value_len);
1472	            if (ret < 0)
1473	              {
1474	                return ret;
1475	              }
1476	            copy_len = value_len;
1477	            if (copy_len > 0 && value_ptr[copy_len - 1] == '\0')
1478	              {
1479	                copy_len--;
1480	              }
1481	            if (copy_len > IW_ESSID_MAX_SIZE)
1482	              {
1483	                copy_len = IW_ESSID_MAX_SIZE;
1484	              }
1485	            if (copy_len > 0)
1486	              {
1487	                memcpy(record->ssid, value_ptr, copy_len);
1488	              }
1489	            record->ssid[copy_len] = '\0';
1490	            record->ssid_len = copy_len;
1491	            break;
1492	
1493	          case 3:
1494	          case 5:
1495	          case 6:
1496	            if (wire_type != ESP_HOSTED_PB_WIRE_VARINT)
1497	              {
1498	                return -EINVAL;
1499	              }
1500	            ret = esp_hosted_pb_get_varint(payload, len, &offset, &value);
1501	            if (ret < 0)
1502	              {
1503	                return ret;
1504	              }
1505	            if (field == 3)
1506	              {
1507	                record->channel = value > UINT8_MAX ? UINT8_MAX : value;
1508	              }
1509	            else if (field == 5)
1510	              {
1511	                record->rssi = esp_hosted_pb_int32(value);
1512	              }
1513	            else
1514	              {
1515	                record->authmode = esp_hosted_pb_int32(value);
1516	              }
1517	            break;
1518	
1519	          default:
1520	            ret = esp_hosted_pb_skip_field(payload, len, &offset, wire_type);
1521	            if (ret < 0)
1522	              {
1523	                return ret;
1524	              }
1525	            break;
1526	        }
1527	    }
1528	
1529	  return have_bssid ? OK : -EINVAL;
1530	}
