1532	static int esp_hosted_parse_scan_records_response(
1533	  FAR struct esp_hosted_driver_s *priv, FAR const uint8_t *payload,
1534	  size_t len)
1535	{
1536	  struct esp_hosted_scan_record_s records[ESP_HOSTED_SCAN_MAX_APS];
1537	  size_t offset = 0;
1538	  int32_t resp = 0;
1539	  uint32_t number = 0;
1540	  uint16_t count = 0;
1541	  int ret;
1542	
1543	  memset(records, 0, sizeof(records));
1544	
1545	  while (offset < len)
1546	    {
1547	      FAR const uint8_t *value_ptr;
1548	      uint64_t key;
1549	      uint64_t value;
1550	      size_t value_len;
1551	      uint32_t field;
1552	      uint8_t wire_type;
1553	
1554	      ret = esp_hosted_pb_get_varint(payload, len, &offset, &key);
1555	      if (ret < 0 || key == 0)
1556	        {
1557	          return -EINVAL;
1558	        }
1559	
1560	      field = key >> 3;
1561	      wire_type = key & 0x07;
1562	
1563	      switch (field)
1564	        {
1565	          case 1:
1566	          case 2:
1567	            if (wire_type != ESP_HOSTED_PB_WIRE_VARINT)
1568	              {
1569	                return -EINVAL;
1570	              }
1571	            ret = esp_hosted_pb_get_varint(payload, len, &offset, &value);
1572	            if (ret < 0)
1573	              {
1574	                return ret;
1575	              }
1576	            if (field == 1)
1577	              {
1578	                resp = esp_hosted_pb_int32(value);
1579	              }
1580	            else
1581	              {
1582	                number = value;
1583	              }
1584	            break;
1585	
1586	          case 3:
1587	            if (wire_type != ESP_HOSTED_PB_WIRE_LENGTH)
1588	              {
1589	                return -EINVAL;
1590	              }
1591	            ret = esp_hosted_pb_get_bytes(payload, len, &offset,
1592	                                           &value_ptr, &value_len);
1593	            if (ret < 0)
1594	              {
1595	                return ret;
1596	              }
1597	            if (count < ESP_HOSTED_SCAN_MAX_APS)
1598	              {
1599	                ret = esp_hosted_parse_ap_record(&records[count],
1600	                                                  value_ptr, value_len);
1601	                if (ret < 0)
1602	                  {
1603	                    return ret;
1604	                  }
1605	                count++;
1606	              }
1607	            break;
1608	
1609	          default:
1610	            ret = esp_hosted_pb_skip_field(payload, len, &offset, wire_type);
1611	            if (ret < 0)
1612	              {
1613	                return ret;
1614	              }
1615	            break;
1616	        }
1617	    }
1618	
1619	  if (resp != 0)
1620	    {
1621	      priv->stats.wlan_scan_get_records_error_count++;
1622	      nwarn("ESP-Hosted scan records failed: resp=%" PRId32 "\n", resp);
1623	      return -EIO;
1624	    }
1625	
1626	  memcpy(priv->scan_records, records, sizeof(records));
1627	  priv->scan_result_count = count;
1628	  priv->scan_ap_available = number > ESP_HOSTED_SCAN_MAX_APS ?
1629	                            ESP_HOSTED_SCAN_MAX_APS : number;
1630	  priv->scan_records_valid = true;
1631	  priv->scan_done = true;
1632	  priv->scan_in_progress = false;
1633	  priv->stats.wlan_scan_get_records_count++;
1634	  priv->stats.wlan_scan_result_count += count;
1635	
1636	  ninfo("ESP-Hosted scan records: reported=%" PRIu32 " cached=%u\n",
1637	        number, count);
1638	  return OK;
1639	}
