1693	static int esp_hosted_parse_control_frame(FAR struct esp_hosted_driver_s *priv,
1694	                                           FAR const uint8_t *payload,
1695	                                           uint16_t len)
1696	{
1697	  FAR const uint8_t *rpc_payload;
1698	  size_t rpc_len;
1699	  struct esp_hosted_rpc_message_s msg;
1700	  int ret;
1701	
1702	  ret = esp_hosted_pserial_unwrap(priv, payload, len, &rpc_payload,
1703	                                   &rpc_len);
1704	  if (ret < 0)
1705	    {
1706	      priv->stats.rpc_malformed_count++;
1707	      return ret;
1708	    }
1709	
1710	  ret = esp_hosted_parse_rpc_message(rpc_payload, rpc_len, &msg);
1711	  if (ret < 0)
1712	    {
1713	      priv->stats.rpc_malformed_count++;
1714	      return ret;
1715	    }
1716	
1717	  priv->stats.rpc_last_uid = msg.uid;
1718	
1719	  if (msg.msg_type == ESP_HOSTED_RPC_TYPE_RESP)
1720	    {
1721	      priv->stats.rpc_response_count++;
1722	      priv->stats.rpc_last_response_id = msg.msg_id;
1723	
1724	      if (msg.payload_field != msg.msg_id)
1725	        {
1726	          priv->stats.rpc_malformed_count++;
1727	          return -EINVAL;
1728	        }
1729	
1730	      switch (msg.msg_id)
1731	        {
1732	          int32_t resp;
1733	
1734	          case ESP_HOSTED_RPC_RESP_GET_MAC_ADDRESS:
1735	            return esp_hosted_parse_mac_response(priv, msg.payload,
1736	                                                 msg.payload_len);
1737	
1738	          case ESP_HOSTED_RPC_RESP_GET_COPROCESSOR_FWVERSION:
1739	            return esp_hosted_parse_fwversion_response(priv, msg.payload,
1740	                                                        msg.payload_len);
1741	
1742	          case ESP_HOSTED_RPC_RESP_SET_MODE:
1743	          case ESP_HOSTED_RPC_RESP_WIFI_INIT:
1744	          case ESP_HOSTED_RPC_RESP_WIFI_START:
1745	          case ESP_HOSTED_RPC_RESP_WIFI_CONNECT:
1746	          case ESP_HOSTED_RPC_RESP_WIFI_DISCONNECT:
1747	          case ESP_HOSTED_RPC_RESP_WIFI_SET_CONFIG:
1748	          case ESP_HOSTED_RPC_RESP_WIFI_SCAN_START:
1749	            ret = esp_hosted_parse_response_status(msg.payload,
1750	                                                    msg.payload_len, &resp);
1751	            if (ret < 0)
1752	              {
1753	                return ret;
1754	              }
1755	            if (resp != 0)
1756	              {
1757	                priv->stats.rpc_malformed_count++;
1758	                nwarn("ESP-Hosted RPC response failed: id=%" PRIu32
1759	                      " resp=%" PRId32 "\n", msg.msg_id, resp);
1760	                return -EIO;
1761	              }
1762	            ninfo("ESP-Hosted RPC response OK: id=%" PRIu32
1763	                  " uid=%" PRIu32 "\n", msg.msg_id, msg.uid);
1764	            return OK;
1765	
1766	          case ESP_HOSTED_RPC_RESP_WIFI_SCAN_GET_AP_RECORDS:
1767	            return esp_hosted_parse_scan_records_response(priv, msg.payload,
1768	                                                           msg.payload_len);
1769	
1770	          default:
1771	            ninfo("ESP-Hosted RPC response: id=%" PRIu32 " uid=%" PRIu32
1772	                  " len=%zu\n", msg.msg_id, msg.uid, msg.payload_len);
1773	            return OK;
1774	        }
1775	    }
1776	  else if (msg.msg_type == ESP_HOSTED_RPC_TYPE_EVENT)
1777	    {
1778	      priv->stats.rpc_event_count++;
1779	
1780	      switch (msg.msg_id)
1781	        {
1782	          case ESP_HOSTED_RPC_EVENT_STA_SCAN_DONE:
1783	            return esp_hosted_parse_sta_scan_done_event(priv, msg.payload,
1784	                                                         msg.payload_len);
1785	
1786	          case ESP_HOSTED_RPC_EVENT_STA_CONNECTED:
1787	            return esp_hosted_parse_sta_connected_event(priv, msg.payload,
1788	                                                         msg.payload_len);
1789	
1790	          case ESP_HOSTED_RPC_EVENT_STA_DISCONNECTED:
1791	            return esp_hosted_parse_sta_disconnected_event(priv, msg.payload,
1792	                                                            msg.payload_len);
1793	
1794	          default:
1795	            ninfo("ESP-Hosted RPC event: id=%" PRIu32 " uid=%" PRIu32
1796	                  " len=%zu\n", msg.msg_id, msg.uid, msg.payload_len);
1797	            return OK;
1798	        }
1799	    }
1800	
1801	  priv->stats.rpc_malformed_count++;
1802	  return -EINVAL;
1803	}
