1805	static int esp_hosted_parse_priv_frame(FAR struct esp_hosted_driver_s *priv,
1806	                                        FAR const uint8_t *payload,
1807	                                        uint16_t len)
1808	{
1809	  uint8_t event_type;
1810	  uint8_t event_len;
1811	
1812	  priv->stats.rx_priv_count++;
1813	
1814	  if (len < ESP_HOSTED_PRIV_EVENT_HDR_LEN)
1815	    {
1816	      return -EINVAL;
1817	    }
1818	
1819	  event_type = payload[0];
1820	  event_len = payload[1];
1821	
1822	  if (event_len + ESP_HOSTED_PRIV_EVENT_HDR_LEN > len)
1823	    {
1824	      return -EINVAL;
1825	    }
1826	
1827	  if (event_type == ESP_HOSTED_PRIV_EVENT_INIT)
1828	    {
1829	      priv->stats.rx_init_event_count++;
1830	      priv->init_seen = true;
1831	      if (!priv->startup_probe_sent)
1832	        {
1833	          priv->startup_probe_pending = true;
1834	        }
1835	      ninfo("ESP-Hosted INIT event received: len=%u\n", event_len);
1836	    }
1837	  else
1838	    {
1839	      ninfo("ESP-Hosted private event: type=%02x len=%u\n",
1840	            event_type, event_len);
1841	    }
1842	
1843	  return OK;
1844	}
