1846	static int esp_hosted_parse_rx_frame(FAR struct esp_hosted_driver_s *priv,
1847	                                      FAR uint8_t *frame)
1848	{
1849	  FAR struct esp_hosted_payload_header_s *header;
1850	  FAR uint8_t *payload;
1851	  enum esp_hosted_if_type_e if_type;
1852	  uint16_t len;
1853	  uint16_t offset;
1854	  uint16_t checksum;
1855	  uint16_t expected;
1856	  int ret = OK;
1857	
1858	  header = (FAR struct esp_hosted_payload_header_s *)frame;
1859	  if_type = ESP_HOSTED_HDR_IF_TYPE(header);
1860	  len = le16toh(header->len);
1861	  offset = le16toh(header->offset);
1862	
1863	  if (len == 0)
1864	    {
1865	      priv->stats.rx_dummy_count++;
1866	      return OK;
1867	    }
1868	
1869	  if (len > ESP_HOSTED_MAX_PAYLOAD || offset != ESP_HOSTED_HEADER_LEN ||
1870	      offset + len > ESP_HOSTED_SDIO_MAX_FRAME)
1871	    {
1872	      priv->stats.malformed_frame_count++;
1873	      return -EINVAL;
1874	    }
1875	
1876	  checksum = le16toh(header->checksum);
1877	  expected = esp_hosted_frame_checksum(frame, offset + len);
1878	  if (checksum != expected)
1879	    {
1880	      priv->stats.checksum_error_count++;
1881	      return -EIO;
1882	    }
1883	
1884	  priv->stats.rx_frame_count++;
1885	  payload = frame + offset;
1886	
1887	  switch (if_type)
1888	    {
1889	      case ESP_HOSTED_STA_IF:
1890	        priv->stats.rx_sta_count++;
1891	        ret = esp_hosted_queue_sta_frame(priv, payload, len);
1892	        break;
1893	
1894	      case ESP_HOSTED_AP_IF:
1895	        priv->stats.rx_ap_count++;
1896	        break;
1897	
1898	      case ESP_HOSTED_SERIAL_IF:
1899	        priv->stats.rx_control_count++;
1900	        ret = esp_hosted_parse_control_frame(priv, payload, len);
1901	        if (ret < 0)
1902	          {
1903	            priv->stats.malformed_frame_count++;
1904	          }
1905	        break;
1906	
1907	      case ESP_HOSTED_PRIV_IF:
1908	        ret = esp_hosted_parse_priv_frame(priv, payload, len);
1909	        if (ret < 0)
1910	          {
1911	            priv->stats.malformed_frame_count++;
1912	          }
1913	        break;
1914	
1915	      default:
1916	        priv->stats.rx_unknown_count++;
1917	        break;
1918	    }
1919	
1920	  return ret;
1921	}
