1923	static int esp_hosted_build_rpc_request(FAR struct esp_hosted_driver_s *priv,
1924	                                         uint32_t request_id,
1925	                                         FAR uint8_t *payload,
1926	                                         size_t payload_size,
1927	                                         FAR size_t *payload_len)
1928	{
1929	  uint8_t request_payload[256];
1930	  size_t request_len = 0;
1931	  size_t offset = 0;
1932	  uint32_t uid;
1933	  int ret;
1934	
1935	  switch (request_id)
1936	    {
1937	      case ESP_HOSTED_RPC_GET_MAC_ADDRESS:
1938	        ret = esp_hosted_pb_append_varint_field(request_payload,
1939	                                                 sizeof(request_payload),
1940	                                                 &request_len, 1,
1941	                                                 ESP_HOSTED_WIFI_IF_STA);
1942	        if (ret < 0) return ret;
1943	        break;
1944	
1945	      case ESP_HOSTED_RPC_GET_COPROCESSOR_FWVERSION:
1946	        break;
1947	
1948	      case ESP_HOSTED_RPC_SET_MODE:
1949	        ret = esp_hosted_pb_append_varint_field(request_payload,
1950	                                                 sizeof(request_payload),
1951	                                                 &request_len, 1,
1952	                                                 ESP_HOSTED_WIFI_MODE_STA);
1953	        if (ret < 0) return ret;
1954	        break;
1955	
1956	      case ESP_HOSTED_RPC_WIFI_INIT:
1957	        ret = esp_hosted_build_wifi_init_payload(request_payload,
1958	                                                  sizeof(request_payload),
1959	                                                  &request_len);
1960	        if (ret < 0) return ret;
1961	        break;
1962	
1963	      case ESP_HOSTED_RPC_WIFI_START:
1964	      case ESP_HOSTED_RPC_WIFI_CONNECT:
1965	      case ESP_HOSTED_RPC_WIFI_DISCONNECT:
1966	        break;
1967	
1968	      case ESP_HOSTED_RPC_WIFI_SET_CONFIG:
1969	        ret = esp_hosted_build_wifi_set_config_payload(priv, request_payload,
1970	                                                        sizeof(request_payload),
1971	                                                        &request_len);
1972	        if (ret < 0) return ret;
1973	        break;
1974	
1975	      case ESP_HOSTED_RPC_WIFI_SCAN_START:
1976	        break;
1977	
1978	      case ESP_HOSTED_RPC_WIFI_SCAN_GET_AP_RECORDS:
1979	        ret = esp_hosted_pb_append_varint_field(request_payload,
1980	                                                 sizeof(request_payload),
1981	                                                 &request_len, 1,
1982	                                                 priv->scan_request_count);
1983	        if (ret < 0) return ret;
1984	        break;
1985	
1986	      default:
1987	        return -EINVAL;
1988	    }
1989	
1990	  uid = esp_hosted_next_rpc_uid(priv);
1991	
1992	  ret = esp_hosted_pb_append_varint_field(payload, payload_size, &offset,
1993	                                           ESP_HOSTED_RPC_FIELD_MSG_TYPE,
1994	                                           ESP_HOSTED_RPC_TYPE_REQ);
1995	  if (ret < 0) return ret;
1996	
1997	  ret = esp_hosted_pb_append_varint_field(payload, payload_size, &offset,
1998	                                           ESP_HOSTED_RPC_FIELD_MSG_ID,
1999	                                           request_id);
2000	  if (ret < 0) return ret;
2001	
2002	  ret = esp_hosted_pb_append_varint_field(payload, payload_size, &offset,
2003	                                           ESP_HOSTED_RPC_FIELD_UID, uid);
2004	  if (ret < 0) return ret;
2005	
2006	  ret = esp_hosted_pb_append_bytes_field(payload, payload_size, &offset,
2007	                                          request_id, request_payload,
2008	                                          request_len);
2009	  if (ret < 0) return ret;
2010	
2011	  *payload_len = offset;
2012	  priv->stats.rpc_last_uid = uid;
2013	  return OK;
2014	}
