2016	static int esp_hosted_send_rpc_request(FAR struct esp_hosted_driver_s *priv,
2017	                                        uint32_t request_id)
2018	{
2019	  size_t payload_len;
2020	  int parse_ret;
2021	  int ret;
2022	
2023	  ret = nxmutex_lock(&priv->lock);
2024	  if (ret < 0)
2025	    {
2026	      return ret;
2027	    }
2028	
2029	  ret = esp_hosted_build_rpc_request(priv, request_id, priv->rpc_payload,
2030	                                      sizeof(priv->rpc_payload),
2031	                                      &payload_len);
2032	  if (ret < 0)
2033	    {
2034	      priv->stats.rpc_malformed_count++;
2035	      nxmutex_unlock(&priv->lock);
2036	      return ret;
2037	    }
2038	
2039	  ret = esp_hosted_pserial_wrap(priv, ESP_HOSTED_RPC_EP_NAME_RSP,
2040	                                 priv->rpc_payload, payload_len,
2041	                                 priv->rpc_tlv_payload,
2042	                                 sizeof(priv->rpc_tlv_payload),
2043	                                 &payload_len);
2044	  if (ret < 0)
2045	    {
2046	      priv->stats.rpc_malformed_count++;
2047	      nxmutex_unlock(&priv->lock);
2048	      return ret;
2049	    }
2050	
2051	  esp_hosted_build_header(priv, priv->tx_frame, ESP_HOSTED_SERIAL_IF, 0, 0,
2052	                           priv->rpc_tlv_payload, payload_len);
2053	  memset(priv->rx_frame, 0, sizeof(priv->rx_frame));
2054	
2055	  ret = esp_hosted_sdio_exchange_frame(priv, priv->tx_frame, priv->rx_frame);
2056	  if (ret < 0)
2057	    {
2058	      nxmutex_unlock(&priv->lock);
2059	      return ret;
2060	    }
2061	
2062	  priv->stats.rpc_request_count++;
2063	  priv->stats.rpc_last_request_id = request_id;
2064	
2065	  parse_ret = esp_hosted_parse_rx_frame(priv, priv->rx_frame);
2066	  nxmutex_unlock(&priv->lock);
2067	  return parse_ret;
2068	}
