2168	static int esp_hosted_drain_rx(FAR struct esp_hosted_driver_s *priv,
2169	                                bool force_once, unsigned int limit,
2170	                                bool nonblocking)
2171	{
2172	  unsigned int i;
2173	  int drained = 0;
2174	  int ret;
2175	
2176	  if (limit == 0 || limit > ESP_HOSTED_RX_WORK_DRAIN_LIMIT)
2177	    {
2178	      limit = ESP_HOSTED_RX_WORK_DRAIN_LIMIT;
2179	    }
2180	
2181	  for (i = 0; i < limit; i++)
2182	    {
2183	      bool had_dataready = priv->dataready_seen;
2184	
2185	      if (priv->wlan_registered &&
2186	          esp_hosted_rx_queue_depth(priv) >= ESP_HOSTED_RX_QUEUE_HIGH_WATER)
2187	        {
2188	          break;
2189	        }
2190	
2191	      if (!had_dataready && !esp_hosted_sdio_rx_available(priv))
2192	        {
2193	          if (!force_once)
2194	            {
2195	              break;
2196	            }
2197	          force_once = false;
2198	          priv->stats.rx_forced_poll_count++;
2199	        }
2200	
2201	      ret = nonblocking ? nxmutex_trylock(&priv->lock) :
2202	            nxmutex_lock(&priv->lock);
2203	      if (ret < 0)
2204	        {
2205	          return drained > 0 ? drained : ret;
2206	        }
2207	
2208	      if (had_dataready)
2209	        {
2210	          priv->dataready_seen = false;
2211	        }
2212	
2213	      ret = esp_hosted_exchange_dummy_locked(priv);
2214	      nxmutex_unlock(&priv->lock);
2215	      if (ret < 0)
2216	        {
2217	          return drained > 0 ? drained : ret;
2218	        }
2219	
2220	      drained++;
2221	    }
2222	
2223	  return drained;
2224	}
