2226	static void esp_hosted_rx_work(FAR void *arg)
2227	{
2228	  FAR struct esp_hosted_driver_s *priv = arg;
2229	  bool force_poll;
2230	
2231	  if (priv->recovering)
2232	    {
2233	      return;
2234	    }
2235	
2236	  force_poll = priv->rx_force_poll;
2237	  priv->rx_force_poll = false;
2238	
2239	  esp_hosted_drain_rx(priv, force_poll,
2240	                       ESP_HOSTED_RX_WORK_DRAIN_LIMIT, false);
2241	  esp_hosted_run_startup_probe(priv);
2242	  esp_hosted_drain_rx(priv, false,
2243	                       ESP_HOSTED_RX_WORK_DRAIN_LIMIT, false);
2244	
2245	  if (priv->wlan_control_start_pending)
2246	    {
2247	      int ret = esp_hosted_run_wlan_control_start(priv);
2248	      if (ret < 0 && ret != -EAGAIN)
2249	        {
2250	          nwarn("ESP-Hosted STA control start failed: %d\n", ret);
2251	        }
2252	    }
2253	
2254	  esp_hosted_drain_rx(priv, false,
2255	                       ESP_HOSTED_RX_WORK_DRAIN_LIMIT, false);
2256	
2257	  if (priv->wlan_control_started && !priv->have_mac &&
2258	      !priv->mac_probe_sent)
2259	    {
2260	      priv->mac_probe_sent = true;
2261	      int ret = esp_hosted_send_rpc_request(priv,
2262	                                             ESP_HOSTED_RPC_GET_MAC_ADDRESS);
2263	      if (ret < 0)
2264	        {
2265	          priv->mac_probe_sent = false;
2266	        }
2267	    }
2268	
2269	  esp_hosted_drain_rx(priv, false,
2270	                       ESP_HOSTED_RX_WORK_DRAIN_LIMIT, false);
2271	
2272	  if (priv->recovering)
2273	    {
2274	      return;
2275	    }
2276	
2277	  if (priv->wlan_registered &&
2278	      esp_hosted_rx_queue_depth(priv) >= ESP_HOSTED_RX_QUEUE_HIGH_WATER)
2279	    {
2280	      esp_hosted_arm_rx_poll(priv, ESP_HOSTED_RX_POLL_IRQ_BUDGET);
2281	      esp_hosted_schedule_rx_poll(priv);
2282	      return;
2283	    }
2284	
2285	  if (esp_hosted_sdio_rx_available(priv))
2286	    {
2287	      priv->dataready_seen = true;
2288	      esp_hosted_arm_rx_poll(priv, ESP_HOSTED_RX_POLL_IRQ_BUDGET);
2289	      int schedule_ret = esp_hosted_schedule_rx_work(priv);
2290	      if (schedule_ret >= 0)
2291	        {
2292	          return;
2293	        }
2294	    }
2295	
2296	  esp_hosted_schedule_rx_poll(priv);
2297	}
