2299	static void esp_hosted_rx_poll_work(FAR void *arg)
2300	{
2301	  FAR struct esp_hosted_driver_s *priv = arg;
2302	
2303	  if (priv->wlan_registered && priv->ifup && priv->carrier_on)
2304	    {
2305	      priv->rx_force_poll = true;
2306	      esp_hosted_schedule_rx_work(priv);
2307	    }
2308	  else
2309	    {
2310	      esp_hosted_schedule_rx_work(priv);
2311	    }
2312	}
