2351	static int esp_hosted_wlan_transmit(FAR struct netdev_lowerhalf_s *dev,
2352	                                     FAR netpkt_t *pkt)
2353	{
2354	  FAR struct esp_hosted_driver_s *priv =
2355	    (FAR struct esp_hosted_driver_s *)dev;
2356	  unsigned int len;
2357	  int parse_ret = OK;
2358	  int ret;
2359	
2360	  len = netpkt_getdatalen(dev, pkt);
2361	
2362	  if (!priv->ifup)
2363	    {
2364	      priv->stats.netdev_tx_error_count++;
2365	      return -ENETDOWN;
2366	    }
2367	
2368	  if (!priv->carrier_on)
2369	    {
2370	      priv->stats.netdev_tx_error_count++;
2371	      priv->stats.netdev_tx_carrier_off_count++;
2372	      netdev_lower_carrier_off(&priv->lower);
2373	      return -ENETDOWN;
2374	    }
2375	
2376	  if (len > ESP_HOSTED_MAX_PAYLOAD)
2377	    {
2378	      priv->stats.netdev_tx_error_count++;
2379	      priv->stats.netdev_tx_oversize_count++;
2380	      return -EMSGSIZE;
2381	    }
2382	
2383	  ret = nxmutex_lock(&priv->lock);
2384	  if (ret < 0)
2385	    {
2386	      priv->stats.netdev_tx_error_count++;
2387	      return ret;
2388	    }
2389	
2390	  ret = netpkt_copyout(dev, priv->netdev_tx_payload, pkt, len, 0);
2391	  if (ret < 0)
2392	    {
2393	      nxmutex_unlock(&priv->lock);
2394	      priv->stats.netdev_tx_error_count++;
2395	      return ret;
2396	    }
2397	
2398	  esp_hosted_build_header(priv, priv->tx_frame, ESP_HOSTED_STA_IF, 0, 0,
2399	                           priv->netdev_tx_payload, len);
2400	  memset(priv->rx_frame, 0, sizeof(priv->rx_frame));
2401	
2402	  ret = esp_hosted_sdio_exchange_frame(priv, priv->tx_frame, priv->rx_frame);
2403	  if (ret >= 0)
2404	    {
2405	      parse_ret = esp_hosted_parse_rx_frame(priv, priv->rx_frame);
2406	      if (parse_ret < 0)
2407	        {
2408	          priv->stats.netdev_tx_parse_error_count++;
2409	        }
2410	    }
2411	
2412	  nxmutex_unlock(&priv->lock);
2413	
2414	  if (ret < 0)
2415	    {
2416	      priv->stats.netdev_tx_error_count++;
2417	      return ret;
2418	    }
2419	
2420	  priv->stats.netdev_tx_count++;
2421	  netpkt_free(dev, pkt, NETPKT_TX);
2422	  netdev_lower_txdone(dev);
2423	  esp_hosted_arm_rx_poll(priv, ESP_HOSTED_RX_POLL_TX_BUDGET);
2424	  esp_hosted_schedule_rx_poll(priv);
2425	  return OK;
2426	}
