2573	    (FAR struct esp_hosted_driver_s *)dev;
2574	  FAR struct iw_encode_ext *ext;
2575	  int ret;
2576	
2577	  if (iwr == NULL || iwr->u.encoding.pointer == NULL)
2578	    {
2579	      return -EINVAL;
2580	    }
2581	
2582	  if (iwr->u.encoding.length < sizeof(struct iw_encode_ext))
2583	    {
2584	      return -EINVAL;
2585	    }
2586	
2587	  ext = (FAR struct iw_encode_ext *)iwr->u.encoding.pointer;
2588	  if (!set)
2589	    {
2590	      ext->alg = priv->passphrase_len > 0 ? IW_ENCODE_ALG_CCMP :
2591	                 IW_ENCODE_ALG_NONE;
2592	      ext->key_len = 0;
2593	      iwr->u.encoding.flags = IW_ENCODE_NOKEY;
2594	      return OK;
2595	    }
2596	
2597	  if ((iwr->u.encoding.flags & IW_ENCODE_DISABLED) != 0 ||
2598	      ext->alg == IW_ENCODE_ALG_NONE || ext->key_len == 0)
2599	    {
2600	      ret = nxmutex_lock(&priv->lock);
2601	      if (ret < 0)
2602	        {
2603	          return ret;
2604	        }
2605	      memset(priv->passphrase, 0, sizeof(priv->passphrase));
2606	      priv->passphrase_len = 0;
2607	      nxmutex_unlock(&priv->lock);
2608	      return OK;
2609	    }
2610	
2611	  if (ext->key_len > ESP_HOSTED_WIFI_PASSWORD_MAX ||
2612	      iwr->u.encoding.length < sizeof(*ext) + ext->key_len)
2613	    {
2614	      return -EINVAL;
