2683	static size_t esp_hosted_wlan_scan_result_len(
2684	  FAR const struct esp_hosted_driver_s *priv)
2685	{
2686	  size_t len = 0;
2687	  uint16_t i;
2688	
2689	  for (i = 0; i < priv->scan_result_count; i++)
2690	    {
2691	      len += IW_EV_LEN(ap_addr) + IW_EV_LEN(qual) +
2692	             IW_EV_LEN(freq) + IW_EV_LEN(data) + IW_EV_LEN(essid) +
