2699	static int esp_hosted_wlan_format_scan_results(
2700	  FAR struct esp_hosted_driver_s *priv, FAR struct iwreq *iwr)
2701	{
2702	  FAR struct iw_event *iwe;
2703	  FAR char *pointer;
2704	  size_t need_len;
2705	  uint16_t i;
2706	
2707	  if (iwr == NULL)
2708	    {
2709	      return -EINVAL;
2710	    }
2711	
2712	  if (priv->scan_result_count == 0)
2713	    {
2714	      iwr->u.data.length = 0;
2715	      return OK;
2716	    }
2717	
2718	  need_len = esp_hosted_wlan_scan_result_len(priv);
2719	  if (iwr->u.data.pointer == NULL || iwr->u.data.length < need_len)
2720	    {
2721	      iwr->u.data.length = need_len;
2722	      return -E2BIG;
2723	    }
2724	
2725	  pointer = iwr->u.data.pointer;
2726	
2727	  for (i = 0; i < priv->scan_result_count; i++)
2728	    {
2729	      struct esp_hosted_scan_record_s *record = &priv->scan_records[i];
2730	
2731	      iwe = (FAR struct iw_event *)pointer;
2732	      iwe->cmd = SIOCGIWAP;
2733	      iwe->u.ap_addr.sa_family = ARPHRD_ETHER;
2734	      memcpy(iwe->u.ap_addr.sa_data, record->bssid, ESP_HOSTED_MAC_SIZE);
2735	      iwe->len = IW_EV_LEN(ap_addr);
2736	      pointer += iwe->len;
2737	
2738	      iwe = (FAR struct iw_event *)pointer;
2739	      iwe->cmd = SIOCGIWESSID;
2740	      iwe->u.essid.flags = 0;
2741	      iwe->u.essid.length = record->ssid_len;
2742	      iwe->u.essid.pointer = (FAR void *)sizeof(iwe->u.essid);
2743	      memcpy(&iwe->u.essid + 1, record->ssid, iwe->u.essid.length);
2744	      iwe->len = IW_EV_LEN(essid) + ((iwe->u.essid.length + 3) & ~3);
2745	      pointer += iwe->len;
2746	
2747	      iwe = (FAR struct iw_event *)pointer;
2748	      iwe->cmd = IWEVQUAL;
2749	      iwe->u.qual.qual = 0;
2750	      iwe->u.qual.level = record->rssi;
2751	      iwe->u.qual.noise = 0;
2752	      iwe->u.qual.updated = IW_QUAL_DBM | IW_QUAL_ALL_UPDATED;
2753	      iwe->len = IW_EV_LEN(qual);
2754	      pointer += iwe->len;
2755	
2756	      iwe = (FAR struct iw_event *)pointer;
2757	      iwe->cmd = SIOCGIWFREQ;
2758	      iwe->u.freq.e = 0;
2759	      iwe->u.freq.m = record->channel;
2760	      iwe->len = IW_EV_LEN(freq);
2761	      pointer += iwe->len;
2762	
2763	      iwe = (FAR struct iw_event *)pointer;
2764	      iwe->cmd = SIOCGIWENCODE;
2765	      iwe->u.data.flags = record->authmode == ESP_HOSTED_WIFI_AUTH_OPEN ?
2766	                          IW_ENCODE_DISABLED :
2767	                          IW_ENCODE_ENABLED | IW_ENCODE_NOKEY;
2768	      iwe->u.data.length = 0;
2769	      iwe->u.data.pointer = NULL;
2770	      iwe->len = IW_EV_LEN(data);
2771	      pointer += iwe->len;
2772	    }
2773	
2774	  iwr->u.data.length = pointer - (FAR char *)iwr->u.data.pointer;
2775	  return OK;
2776	}
