2778	static int esp_hosted_wlan_scan(FAR struct netdev_lowerhalf_s *dev,
2779	                                 FAR struct iwreq *iwr, bool set)
2780	{
2781	  FAR struct esp_hosted_driver_s *priv =
2782	    (FAR struct esp_hosted_driver_s *)dev;
2783	  int ret;
2784	
2785	  if (!set)
2786	    {
2787	      if (iwr == NULL)
2788	        {
2789	          return -EINVAL;
2790	        }
2791	
2792	      if (priv->scan_in_progress || !priv->scan_done)
2793	        {
2794	          return -EAGAIN;
2795	        }
2796	
2797	      if (priv->scan_status != 0)
2798	        {
2799	          iwr->u.data.length = 0;
