2941	static int esp_hosted_queue_sta_frame(FAR struct esp_hosted_driver_s *priv,
2942	                                       FAR const uint8_t *payload,
2943	                                       uint16_t len)
2944	{
2945	  FAR netpkt_t *pkt;
2946	  irqstate_t flags;
2947	  int ret;
2948	
2949	  if (!priv->wlan_registered)
2950	    {
2951	      priv->stats.netdev_rx_dropped_count++;
2952	      return OK;
2953	    }
2954	
2955	  if (len >= ETH_HDRLEN &&
2956	      memcmp(((FAR const struct eth_hdr_s *)payload)->src, priv->mac,
2957	             ESP_HOSTED_MAC_SIZE) == 0)
2958	    {
2959	      priv->stats.netdev_rx_echo_dropped_count++;
2960	      return OK;
2961	    }
2962	
2963	  pkt = netpkt_alloc(&priv->lower, NETPKT_RX);
2964	  if (pkt == NULL)
2965	    {
2966	      priv->stats.netdev_rx_dropped_count++;
2967	      return -ENOMEM;
2968	    }
2969	
2970	  ret = netpkt_copyin(&priv->lower, pkt, payload, len, 0);
2971	  if (ret < 0)
2972	    {
2973	      priv->stats.netdev_rx_dropped_count++;
2974	      netpkt_free(&priv->lower, pkt, NETPKT_RX);
2975	      return ret;
2976	    }
2977	
2978	  flags = spin_lock_irqsave(&priv->rx_lock);
2979	  ret = netpkt_tryadd_queue(pkt, &priv->rx_queue);
2980	  if (ret >= 0)
2981	    {
2982	      priv->stats.current_rx_queue_depth++;
2983	      if (priv->stats.current_rx_queue_depth >
2984	          priv->stats.rx_queue_max_depth)
2985	        {
2986	          priv->stats.rx_queue_max_depth =
2987	            priv->stats.current_rx_queue_depth;
2988	        }
2989	    }
2990	  spin_unlock_irqrestore(&priv->rx_lock, flags);
2991	
2992	  if (ret < 0)
2993	    {
2994	      priv->stats.netdev_rx_dropped_count++;
2995	      netpkt_free(&priv->lower, pkt, NETPKT_RX);
2996	      return ret;
2997	    }
2998	
2999	  priv->stats.netdev_rx_count++;
3000	  netdev_lower_rxready(&priv->lower);
3001	  return OK;
3002	}
