3004	static int esp_hosted_schedule_rx_work_delay(
3005	  FAR struct esp_hosted_driver_s *priv, clock_t delay, bool idle)
3006	{
3007	  int ret;
3008	
3009	  if (delay > 0)
3010	    {
3011	      if (!work_available(&priv->poll_work))
3012	        {
3013	          return -EBUSY;
3014	        }
3015	      ret = work_queue(ESP_HOSTED_WORK_QUEUE, &priv->poll_work,
3016	                        esp_hosted_rx_poll_work, priv, delay);
3017	      return ret;
3018	    }
3019	
3020	  if (!work_available(&priv->rx_work))
3021	    {
3022	      return -EBUSY;
3023	    }
3024	
3025	  ret = work_queue(ESP_HOSTED_WORK_QUEUE, &priv->rx_work,
3026	                    esp_hosted_rx_work, priv, 0);
3027	  return ret;
3028	}
