3035	static void esp_hosted_arm_rx_poll(FAR struct esp_hosted_driver_s *priv,
3036	                                    uint8_t budget)
3037	{
3038	  if (budget > priv->rx_poll_budget)
3039	    {
3040	      priv->rx_poll_budget = budget;
3041	    }
