3043	
3044	static void esp_hosted_schedule_rx_poll(FAR struct esp_hosted_driver_s *priv)
3045	{
3046	  if (priv->wlan_registered && priv->ifup && priv->carrier_on)
3047	    {
3048	      bool burst = priv->rx_poll_budget > 0;
3049	      int ret;
3050	
3051	      if (burst)
3052	        {
3053	          priv->rx_force_poll = true;
3054	          if (!work_available(&priv->poll_work))
3055	            {
3056	              work_cancel(ESP_HOSTED_WORK_QUEUE, &priv->poll_work);
3057	            }
3058	        }
3059	
3060	      ret = esp_hosted_schedule_rx_work_delay(priv,
3061	                                               MSEC2TICK(burst ?
3062	                                                          ESP_HOSTED_RX_POLL_DELAY_MS :
3063	                                                          ESP_HOSTED_RX_IDLE_POLL_DELAY_MS),
3064	                                               !burst);
3065	      if (ret >= 0 && burst)
3066	        {
3067	          priv->rx_poll_budget--;
3068	        }
3069	      else if (ret < 0 && burst)
3070	        {
3071	          esp_hosted_schedule_rx_work(priv);
3072	        }
3073	    }
3074	}
