#include <nuttx/wireless/esp_hosted.h>

#include "esp32p4_sdmmc.h"

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: esp32p4_wifi_init
 *
 * Description:
 *   Initialize the ESP-Hosted WiFi co-processor over SDIO.
 *   The ESP32-C6 is connected to ESP32-P4 via SDIO bus.
 *
 * Returned Value:
 *   Zero (OK) on success; a negated errno on failure.
 *
 ****************************************************************************/

int esp32p4_wifi_init(void)
{
  struct esp_hosted_sdio_config_s config;
  FAR struct sdio_dev_s *sdio;
  int ret;

  wlinfo("ESP-Hosted: initializing SDIO transport\n");

  /* Initialize the ESP32-P4 SDMMC hardware */

  ret = esp32p4_sdmmc_initialize();
  if (ret < 0)
    {
      wlerr("ERROR: esp32p4_sdmmc_initialize failed: %d\n", ret);
      return ret;
    }

  /* Get the SDIO device handle */

  sdio = esp32p4_sdmmc_getdev();
  if (sdio == NULL)
    {
      wlerr("ERROR: esp32p4_sdmmc_getdev failed\n");
      return -ENODEV;
    }

  /* Initialize ESP-Hosted SDIO transport */

  config.sdio_dev = sdio;

  ret = esp_hosted_sdio_initialize(&config);
  if (ret < 0)
    {
      wlerr("ERROR: esp_hosted_sdio_initialize failed: %d\n", ret);
      return ret;
    }

  wlinfo("ESP-Hosted: SDIO transport ready\n");
  return OK;
}

