    syslog(LOG_INFO, "Step 2: get dev...\n");
    sdio = esp32p4_sdmmc_getdev();
    syslog(LOG_INFO, "Step 2: sdio=%p\n", sdio);
    if (!sdio) goto done;

    /* Step 3: 初始化 ESP-Hosted */
    syslog(LOG_INFO, "Step 3: init ESP-Hosted...\n");
    hosted_config.sdio_dev = sdio;
    hosted_config.block_size = 512;
    ret = esp_hosted_sdio_initialize(&hosted_config);
    syslog(LOG_INFO, "Step 3: ret=%d\n", ret);

done:
    syslog(LOG_INFO, "ESP-Hosted bringup done\n");
  }
#endif
  up_puts("BRINGUP: complete\n");

